screenPanels.initJs:
function(container, apiUrl, tables) {
  let loginAttempts = 0;
  const maxAttempts = 5;
  let isAccountLocked = false;

  // エラーメッセージ表示関数
  function showError(message) {
    const errorDiv = container.querySelector('#error-message');
    errorDiv.textContent = message;
    errorDiv.classList.remove('hidden');
  }

  // エラーメッセージ非表示関数
  function hideError() {
    const errorDiv = container.querySelector('#error-message');
    errorDiv.classList.add('hidden');
  }

  // バリデーション関数
  function validateForm(userId, password) {
    if (!userId && !password) {
      showError('ユーザーIDとパスワードを入力してください');
      return false;
    }
    if (!userId) {
      showError('ユーザーIDを入力してください');
      return false;
    }
    if (!password) {
      showError('パスワードを入力してください');
      return false;
    }
    return true;
  }

  // 特殊文字チェック関数
  function containsSpecialChars(str) {
    const dangerousChars = /<script|<\/script|javascript:|DROP\s+TABLE|SELECT\s+\*|INSERT\s+INTO|DELETE\s+FROM/i;
    return dangerousChars.test(str);
  }

  // ログイン処理関数
  async function handleLogin(userId, password, rememberLogin) {
    // アカウントロックチェック
    if (isAccountLocked) {
      showError('アカウントがロックされました。しばらく時間をおいてから再度お試しください。');
      return;
    }

    // 特殊文字チェック
    if (containsSpecialChars(userId) || containsSpecialChars(password)) {
      showError('不正な文字が含まれています');
      return;
    }

    try {
      // ユーザーテーブルから認証情報を取得
      const users = await window.aivicApi.list(0);
      if (!users) {
        showError('システムエラーが発生しました');
        return;
      }

      // ユーザー認証
      const user = users.find(u => u.ユーザー名 === userId && u.有効フラグ === true);

      if (!user) {
        loginAttempts++;
        if (loginAttempts >= maxAttempts) {
          isAccountLocked = true;
          showError('アカウントがロックされました。しばらく時間をおいてから再度お試しください。');
        } else {
          showError('ユーザーIDまたはパスワードが正しくありません');
        }
        return;
      }

      // パスワード検証（実際の実装ではハッシュ比較）
      // ここでは簡易的にプレーンテキスト比較
      if (user.パスワードハッシュ !== password) {
        loginAttempts++;
        if (loginAttempts >= maxAttempts) {
          isAccountLocked = true;
          showError('アカウントがロックされました。しばらく時間をおいてから再度お試しください。');
        } else {
          showError('ユーザーIDまたはパスワードが正しくありません');
        }
        return;
      }

      // ログイン成功
      loginAttempts = 0; // リセット

      // 最終ログイン日時を更新
      await window.aivicApi.update(0, user.ユーザーID, {
        最終ログイン日時: new Date().toISOString()
      });

      // ログイン状態保持
      if (rememberLogin) {
        localStorage.setItem('loginUser', JSON.stringify({
          userId: user.ユーザーID,
          userName: user.ユーザー名,
          displayName: user.氏名,
          loginTime: new Date().toISOString()
        }));
      } else {
        sessionStorage.setItem('loginUser', JSON.stringify({
          userId: user.ユーザーID,
          userName: user.ユーザー名,
          displayName: user.氏名,
          loginTime: new Date().toISOString()
        }));
      }

      // 工数記録画面に遷移
      window.showScreen("scr-1778907133295");

    } catch (error) {
      console.error('Login error:', error);
      showError('ログイン処理中にエラーが発生しました');
    }
  }

  // ログイン状態チェック（ページ読み込み時）
  function checkExistingLogin() {
    const storedUser = localStorage.getItem('loginUser') || sessionStorage.getItem('loginUser');
    if (storedUser) {
      try {
        const userData = JSON.parse(storedUser);
        // 自動ログイン（工数記録画面に遷移）
        window.showScreen("scr-1778907133295");
        return true;
      } catch (e) {
        // 無効なデータの場合はクリア
        localStorage.removeItem('loginUser');
        sessionStorage.removeItem('loginUser');
      }
    }
    return false;
  }

  // パスワード表示切り替え
  const togglePasswordBtn = container.querySelector('#toggle-password');
  const passwordInput = container.querySelector('#password');

  togglePasswordBtn.addEventListener('click', () => {
    if (passwordInput.type === 'password') {
      passwordInput.type = 'text';
      togglePasswordBtn.textContent = '🙈';
    } else {
      passwordInput.type = 'password';
      togglePasswordBtn.textContent = '👁';
    }
  });

  // ログインフォーム送信処理
  const loginForm = container.querySelector('#login-form');
  loginForm.addEventListener('submit', async (e) => {
    e.preventDefault();
    hideError();

    const userId = container.querySelector('#user-id').value.trim();
    const password = container.querySelector('#password').value;
    const rememberLogin = container.querySelector('#remember-login').checked;

    if (!validateForm(userId, password)) {
      return;
    }

    await handleLogin(userId, password, rememberLogin);
  });

  // パスワード忘れリンク
  const forgotPasswordLink = container.querySelector('#forgot-password-link');
  forgotPasswordLink.addEventListener('click', (e) => {
    e.preventDefault();
    // パスワードリセット画面に遷移（実装時に適切な画面IDに変更）
    alert('パスワードリセット機能は準備中です');
  });

  // ログインボタンホバー効果
  const loginBtn = container.querySelector('#login-btn');
  loginBtn.addEventListener('mouseenter', () => {
    loginBtn.style.background = 'var(--primary-hover)';
  });
  loginBtn.addEventListener('mouseleave', () => {
    loginBtn.style.background = 'var(--primary)';
  });

  // 初期化時にログイン状態をチェック
  if (!checkExistingLogin()) {
    // 既存ログインがない場合、フォームにフォーカス
    container.querySelector('#user-id').focus();
  }
}

function(container, apiUrl, tables) {
  let currentWorkRecord = null;
  let startTime = null;
  let elapsedTimer = null;
  let pauseStartTime = null;
  let totalPauseTime = 0;
  let currentPauseRecord = null;

  // 現在日時更新
  function updateDateTime() {
    const now = new Date();
    const dateStr = now.toLocaleDateString('ja-JP', { 
      year: 'numeric', month: '2-digit', day: '2-digit', weekday: 'short' 
    });
    const timeStr = now.toLocaleTimeString('ja-JP', { 
      hour: '2-digit', minute: '2-digit', second: '2-digit' 
    });

    container.querySelector('#current-date').textContent = dateStr;
    container.querySelector('#current-time').textContent = timeStr;
  }

  // 経過時間更新
  function updateElapsedTime() {
    if (!startTime) return;

    const now = new Date();
    let elapsed = now - startTime - totalPauseTime;

    if (pauseStartTime) {
      // 中断中は中断開始時点での経過時間を表示
      elapsed = pauseStartTime - startTime - totalPauseTime;
    }

    const hours = Math.floor(elapsed / (1000 * 60 * 60));
    const minutes = Math.floor((elapsed % (1000 * 60 * 60)) / (1000 * 60));
    const seconds = Math.floor((elapsed % (1000 * 60)) / 1000);

    const timeStr = `${hours.toString().padStart(2, '0')}:${minutes.toString().padStart(2, '0')}:${seconds.toString().padStart(2, '0')}`;
    container.querySelector('#elapsed-time').textContent = timeStr;
  }

  // 作業項目読み込み
  async function loadWorkItems() {
    const workItems = await window.aivicApi.list(3); // 作業項目マスタ
    const select = container.querySelector('#work-item-select');

    if (workItems) {
      select.innerHTML = '<option value="">選択してください</option>';
      workItems
        .filter(item => item.有効フラグ)
        .sort((a, b) => (a.表示順序 || 0) - (b.表示順序 || 0))
        .forEach(item => {
          const option = document.createElement('option');
          option.value = item.id;
          option.textContent = `${item.作業項目コード} - ${item.作業項目名}`;
          select.appendChild(option);
        });
    }
  }

  // 作業履歴描画
  function renderHistory(records) {
    const tbody = container.querySelector('#history-tbody');
    const today = new Date().toDateString();

    const todayRecords = records.filter(record => {
      const recordDate = new Date(record.作業日).toDateString();
      return recordDate === today;
    }).sort((a, b) => new Date(a.作業開始時刻) - new Date(b.作業開始時刻));

    tbody.innerHTML = todayRecords.map(record => {
      const startTime = new Date(record.作業開始時刻).toLocaleTimeString('ja-JP', { 
        hour: '2-digit', minute: '2-digit' 
      });
      const endTime = record.作業終了時刻? 
        new Date(record.作業終了時刻).toLocaleTimeString('ja-JP', { 
          hour: '2-digit', minute: '2-digit' 
        }) : '-';

      const workHours = record.作業時間 ? 
        `${Math.floor(record.作業時間 / 60)}:${(record.作業時間 % 60).toString().padStart(2, '0')}` : '-';

      const statusBadge = record.進捗状況 === '作業中' ? 
        `<span style="background: var(--primary); color: #fff; padding: 2px 6px; border-radius: 4px; font-size: 10px;">${record.進捗状況}</span>` :
        record.進捗状況 === '中断' ?
        `<span style="background: #ff6a00; color: #fff; padding: 2px 6px; border-radius: 4px; font-size: 10px;">${record.進捗状況}</span>` :
        `<span style="background: rgba(255,255,255,0.1); color: var(--text); padding: 2px 6px; border-radius: 4px; font-size: 10px;">${record.進捗状況}</span>`;

      return `
        <tr data-id="${record.id}" style="border-bottom: 1px solid rgba(255,255,255,0.05);">
          <td style="padding: 6px 8px; color: var(--text);">${startTime}</td>
          <td style="padding: 6px 8px; color: var(--text);">${endTime}</td>
          <td style="padding: 6px 8px; color: var(--text);">${record.プロジェクト名 || '-'}</td>
          <td style="padding: 6px 8px; text-align: right; color: var(--text);">${workHours}</td>
          <td style="padding: 6px 8px; text-align: center;">${statusBadge}</td>
        </tr>
      `;
    }).join('');
  }

  // 初期データ読み込み
  async function loadInitialData() {
    updateDateTime();
    await loadWorkItems();

    const records = await window.aivicApi.list(1); // 作業記録
    if (records) {
      renderHistory(records);
    }
  }

  // 作業開始
  container.querySelector('#btn-start-work').addEventListener('click', async () => {
    const workItemId = container.querySelector('#work-item-select').value;
    if (!workItemId) {
      alert('作業項目を選択してください');
      return;
    }

    const workItems = await window.aivicApi.list(3);
    const selectedItem = workItems?.find(item => item.id === workItemId);

    const now = new Date();
    const workRecord = {
      作業員ID: 'current-user-id', // 実際の実装では認証されたユーザーIDを使用
      作業日: now.toISOString().split('T')[0],
      作業開始時刻: now.toISOString(),
      プロジェクト名: selectedItem?.作業項目名|| '',
      作業場所: '現場A', // 実際の実装では選択可能にする
      作業種別: selectedItem?.カテゴリ || '',
      作業内容: '',
      進捗状況: '作業中',
      承認状態: '未承認',
      作成者ID: 'current-user-id'
    };

    const saved = await window.aivicApi.save(1, workRecord);
    if (saved) {
      currentWorkRecord = saved;
      startTime = now;
      totalPauseTime = 0;
      pauseStartTime = null;

      container.querySelector('#btn-start-work').disabled = true;
      container.querySelector('#btn-end-work').disabled = false;
      container.querySelector('#btn-pause-work').disabled = false;
      container.querySelector('#work-status').textContent = '作業中';

      elapsedTimer = setInterval(updateElapsedTime, 1000);
      updateElapsedTime();

      const records = await window.aivicApi.list(1);
      if (records) renderHistory(records);
    }
  });

  // 作業終了
  container.querySelector('#btn-end-work').addEventListener('click', async () => {
    if (!currentWorkRecord) {
      alert('作業が開始されていません');
      return;
    }

    const now = new Date();
    let workTime = Math.floor((now - startTime - totalPauseTime) / (1000 * 60));

    // 中断中の場合は中断時点までの時間
    if (pauseStartTime) {
      workTime = Math.floor((pauseStartTime - startTime - totalPauseTime) / (1000 * 60));
    }

    const memo = container.querySelector('#work-memo').value;

    const updated = await window.aivicApi.update(1, currentWorkRecord.id, {
      作業終了時刻: now.toISOString(),
      作業時間: workTime,
      作業内容: memo,
      進捗状況: '完了'
    });

    if (updated) {
      // 中断記録がある場合は終了
      if (currentPauseRecord) {
        await window.aivicApi.update(2, currentPauseRecord.id, {
          中断終了日時: now.toISOString(),
          中断時間: Math.floor((now - new Date(currentPauseRecord.中断開始日時)) / (1000 * 60)),
          対応状況: '解決済み'
        });
      }

      currentWorkRecord = null;
      startTime = null;
      pauseStartTime = null;
      currentPauseRecord = null;
      totalPauseTime = 0;

      clearInterval(elapsedTimer);

      container.querySelector('#btn-start-work').disabled = false;
      container.querySelector('#btn-end-work').disabled = true;
      container.querySelector('#btn-pause-work').disabled = true;
      container.querySelector('#work-status').textContent = '待機中';
      container.querySelector('#elapsed-time').textContent = '00:00:00';
      container.querySelector('#work-memo').value = '';
      container.querySelector('#work-item-select').value = '';

      const records = await window.aivicApi.list(1);
      if (records) renderHistory(records);
    }
  });

  // 作業中断
  container.querySelector('#btn-pause-work').addEventListener('click', () => {
    if (!currentWorkRecord) {
      alert('作業が開始されていません');
      return;
    }

    container.querySelector('#pause-dialog').classList.remove('hidden');
  });

  // 中断ダイアログ - キャンセル
  container.querySelector('#btn-pause-cancel').addEventListener('click', () => {
    container.querySelector('#pause-dialog').classList.add('hidden');
    container.querySelector('#pause-reason-category').value = '';
    container.querySelector('#pause-reason-detail').value = '';
  });

  // 中断ダイアログ - 決定
  container.querySelector('#btn-pause-confirm').addEventListener('click', async () => {
    const category = container.querySelector('#pause-reason-category').value;
    const detail = container.querySelector('#pause-reason-detail').value;

    if (!category) {
      alert('中断理由を選択してください');
      return;
    }

    const now = new Date();
    const pauseRecord = {
      作業記録ID: currentWorkRecord.id,
      中断開始日時: now.toISOString(),
      中断理由区分: category,
      中断理由詳細: detail,
      影響度: '中程度',
      対応状況: '対応中',
      記録者ID: 'current-user-id'
    };

    const saved = await window.aivicApi.save(2, pauseRecord);
    if (saved) {
      currentPauseRecord = saved;
      pauseStartTime = now;

      await window.aivicApi.update(1, currentWorkRecord.id, {
        進捗状況: '中断'
      });

      container.querySelector('#work-status').textContent = '中断中';
      container.querySelector('#pause-dialog').classList.add('hidden');
      container.querySelector('#pause-reason-category').value = '';
      container.querySelector('#pause-reason-detail').value = '';

      const records = await window.aivicApi.list(1);
      if (records) renderHistory(records);
    }
  });

  // 履歴更新
  container.querySelector('#btn-refresh-history').addEventListener('click', async () => {
    const records = await window.aivicApi.list(1);
    if (records) renderHistory(records);
  });

  // 保存
  container.querySelector('#btn-save').addEventListener('click', async () => {
    if (currentWorkRecord) {
      const memo = container.querySelector('#work-memo').value;
      await window.aivicApi.update(1, currentWorkRecord.id, {
        作業内容: memo
      });
      alert('作業メモを保存しました');
    } else {
      alert('保存する作業記録がありません');
    }
  });

  // キャンセル
  container.querySelector('#btn-cancel').addEventListener('click', () => {
    if (currentWorkRecord) {
      if (confirm('作業中のデータが失われますが、よろしいですか？')) {
        // 作業をキャンセル（実際の実装では作業記録を削除または無効化）
        currentWorkRecord = null;
        startTime = null;
        pauseStartTime = null;
        totalPauseTime = 0;
        clearInterval(elapsedTimer);

        container.querySelector('#btn-start-work').disabled = false;
        container.querySelector('#btn-end-work').disabled = true;
        container.querySelector('#btn-pause-work').disabled = true;
        container.querySelector('#work-status').textContent = '待機中';
        container.querySelector('#elapsed-time').textContent = '00:00:00';
        container.querySelector('#work-memo').value = '';
        container.querySelector('#work-item-select').value = '';
      }
    }
  });

  // ナビゲーション
  container.querySelector('#btn-work-record-start').addEventListener('click', () => {
    window.showScreen("scr-1778907187615");
  });

  container.querySelector('#btn-work-history').addEventListener('click', () => {
    window.showScreen("scr-1778907145716");
  });

  container.querySelector('#btn-emergency-report').addEventListener('click', () => {
    window.showScreen("scr-1778907330826");
  });

  // 文字数カウント
  container.querySelector('#work-memo').addEventListener('input', (e) => {
    container.querySelector('#memo-count').textContent = e.target.value.length;
  });

  container.querySelector('#pause-reason-detail').addEventListener('input', (e) => {
    container.querySelector('#pause-detail-count').textContent = e.target.value.length;
  });

  // 定期更新
  setInterval(updateDateTime, 1000);

  // 初期化
  loadInitialData();
}

function(container, apiUrl, tables) {
  const tbody = container.querySelector("#work-history-tbody");
  const noResults = container.querySelector("#no-results");
  const errorMessage = container.querySelector("#error-message");
  const workItemSelect = container.querySelector("#filter-work-item");

  let allWorkRecords = [];
  let allWorkItems = [];
  let allInterruptions = [];

  // エラーメッセージ表示関数
  function showError(message) {
    errorMessage.textContent = message;
    errorMessage.classList.remove("hidden");
    setTimeout(() => {
      errorMessage.classList.add("hidden");
    }, 5000);
  }

  // 日付バリデーション関数
  function validateDateRange(startDate, endDate) {
    if (!startDate || !endDate) {
      return "日付範囲を選択してください";
    }

    const start = new Date(startDate);
    const end = new Date(endDate);
    const today = new Date();
    today.setHours(23, 59, 59, 999);

    if (start > today || end > today) {
      return "未来日付は選択できません";
    }

    if (start > end) {
      return "開始日は終了日より前の日付を入力してください";
    }

    const oneYear = 365 * 24 * 60 * 60 * 1000;
    if (end - start > oneYear) {
      return "1年以上の期間は選択できません";
    }

    return null;
  }

  // 中断回数を計算する関数
  function getInterruptionCount(workRecordId) {
    return allInterruptions.filter(interruption => 
      interruption.作業記録ID === workRecordId
    ).length;
  }

  // 作業時間をフォーマットする関数
  function formatWorkTime(minutes) {
    if (!minutes) return "-";
    const hours = Math.floor(minutes / 60);
    const mins = minutes % 60;
    return `${hours}:${mins.toString().padStart(2, '0')}`;
  }

  // 日時フォーマット関数
  function formatDateTime(dateTimeStr) {
    if (!dateTimeStr) return "-";
    const date = new Date(dateTimeStr);
    return date.toLocaleString('ja-JP', {
      year: 'numeric',
      month: '2-digit',
      day: '2-digit',
      hour: '2-digit',
      minute: '2-digit'
    });
  }

  // 時刻フォーマット関数
  function formatTime(dateTimeStr) {
    if (!dateTimeStr) return "-";
    const date = new Date(dateTimeStr);
    return date.toLocaleString('ja-JP', {
      hour: '2-digit',
      minute: '2-digit'
    });
  }

  // テーブル再描画関数
  function renderRows(rows) {
    if (rows.length === 0) {
      tbody.innerHTML = "";
      noResults.classList.remove("hidden");
      return;
    }

    noResults.classList.add("hidden");
    tbody.innerHTML = rows.map(record => {
      const workItem = allWorkItems.find(item => item.作業項目ID === record.作業項目ID);
      const interruptionCount = getInterruptionCount(record.作業記録ID);

      return `
        <tr data-id="${record.作業記録ID}" style="height: 34px;">
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${formatDateTime(record.作業日)}</td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${workItem ? workItem.作業項目名 : record.作業種別 || "-"}</td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${formatTime(record.作業開始時刻)}</td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${formatTime(record.作業終了時刻)}</td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${formatWorkTime(record.作業時間)}</td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text); text-align: center;">${interruptionCount}</td>
          <td style="padding: 6px 10px; font-size: 13px;">
            <span style="padding: 2px 6px; border-radius: 4px; font-size: 11px; font-weight: 500; 
              ${record.進捗状況 === '完了' ? 'background: rgba(34, 197, 94, 0.2); color: #86efac;' : 
                record.進捗状況 === '作業中' ? 'background: rgba(59, 130, 246, 0.2); color: #93c5fd;' : 
                'background: rgba(245, 158, 11, 0.2); color: #fbbf24;'}">${record.進捗状況}</span>
          </td>
          <td style="padding: 6px 10px;">
            <button class="action-btn secondary detail-btn" data-id="${record.作業記録ID}" style="font-size: 11px; padding: 4px 8px;">詳細確認</button>
          </td>
        </tr>
      `;
    }).join("");
  }

  // 作業項目セレクトボックスを更新
  function updateWorkItemSelect() {
    workItemSelect.innerHTML = '<option value="">すべて</option>';
    allWorkItems.forEach(item => {
      workItemSelect.innerHTML += `<option value="${item.作業項目ID}">${item.作業項目名}</option>`;
    });
  }

  // フィルタリング関数
  function filterRecords() {
    const startDate = container.querySelector("#filter-start-date").value;
    const endDate = container.querySelector("#filter-end-date").value;
    const workItemId = container.querySelector("#filter-work-item").value;
    const status = container.querySelector("#filter-status").value;

    let filtered = [...allWorkRecords];

    // 日付範囲フィルター
    if (startDate && endDate) {
      const validation = validateDateRange(startDate, endDate);
      if (validation) {
        showError(validation);
        return;
      }

      filtered = filtered.filter(record => {
        const recordDate = new Date(record.作業日).toISOString().split('T')[0];
        return recordDate >= startDate && recordDate <= endDate;
      });
    } else if (startDate || endDate) {
      showError("日付範囲を選択してください");
      return;
    }

    // 作業項目フィルター
    if (workItemId) {
      filtered = filtered.filter(record => record.作業項目ID === workItemId);
    }

    // 作業状況フィルター
    if (status) {
      filtered = filtered.filter(record => record.進捗状況 === status);
    }

    // 日付降順でソート
    filtered.sort((a, b) => new Date(b.作業日) - new Date(a.作業日));

    renderRows(filtered);
  }

  // CSVエクスポート関数
  function exportCSV() {
    const headers = ['作業日時', '作業項目名', '開始時刻', '終了時刻', '作業時間', '中断回数', '進捗状況', '作業内容', '作業場所'];
    const csvData = [headers];

    allWorkRecords.forEach(record => {
      const workItem = allWorkItems.find(item => item.作業項目ID === record.作業項目ID);
      const interruptionCount = getInterruptionCount(record.作業記録ID);

      csvData.push([
        formatDateTime(record.作業日),
        workItem ? workItem.作業項目名 : record.作業種別 || "",
        formatTime(record.作業開始時刻),
        formatTime(record.作業終了時刻),
        formatWorkTime(record.作業時間),
        interruptionCount,
        record.進捗状況 || "",
        record.作業内容 || "",
        record.作業場所 || ""
      ]);
    });

    const csvContent = "\uFEFF" + csvData.map(row => 
      row.map(field => `"${String(field).replace(/"/g, '""')}"`).join(",")
    ).join("\n");

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement("a");
    link.href = URL.createObjectURL(blob);
    link.download = `作業履歴一覧_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  }

  // 初期データ読み込み
  async function loadInitialData() {
    try {
      // 作業記録データ
      const workRecords = await window.aivicApi.list(1);
      if (workRecords) {
        allWorkRecords = workRecords;
      } else {
        allWorkRecords = tables[1]?.records || [];
      }

      // 作業項目マスタ
      const workItems = await window.aivicApi.list(3);
      if (workItems) {
        allWorkItems = workItems;
      } else {
        allWorkItems = tables[3]?.records || [];
      }

      // 中断記録
      const interruptions = await window.aivicApi.list(2);
      if (interruptions) {
        allInterruptions = interruptions;
      } else {
        allInterruptions = tables[2]?.records || [];
      }

      updateWorkItemSelect();

      // 日付降順でソート
      allWorkRecords.sort((a, b) => new Date(b.作業日) - new Date(a.作業日));
      renderRows(allWorkRecords);
    } catch (error) {
      console.error("データ読み込みエラー:", error);
      // フォールバック: 初期データを使用
      allWorkRecords = tables[1]?.records || [];
      allWorkItems = tables[3]?.records || [];
      allInterruptions = tables[2]?.records || [];
      updateWorkItemSelect();
      allWorkRecords.sort((a, b) => new Date(b.作業日) - new Date(a.作業日));
      renderRows(allWorkRecords);
    }
  }

  // 検索ボタンイベント
  container.querySelector("#btn-search").addEventListener("click", filterRecords);

  // リセットボタンイベント
  container.querySelector("#btn-reset").addEventListener("click", () => {
    container.querySelector("#filter-start-date").value = "";
    container.querySelector("#filter-end-date").value = "";
    container.querySelector("#filter-work-item").value = "";
    container.querySelector("#filter-status").value = "";
    errorMessage.classList.add("hidden");
    allWorkRecords.sort((a, b) => new Date(b.作業日) - new Date(a.作業日));
    renderRows(allWorkRecords);
  });

  // CSVエクスポートボタンイベント
  container.querySelector("#btn-export").addEventListener("click", exportCSV);

  // 画面遷移ボタンイベント
  container.querySelector("#btn-extract").addEventListener("click", () => {
    window.showScreen("scr-1778907353387");
  });

  container.querySelector("#btn-back").addEventListener("click", () => {
    window.showScreen("scr-1778907133295");
  });

  // 行レベル操作のイベントデリゲーション
  container.addEventListener("click", (e) => {
    const detailBtn = e.target.closest(".detail-btn");
    if (detailBtn) {
      window.showScreen("scr-1778907367889");
    }
  });

  // 初期データ読み込み実行
  loadInitialData();
}

function(container, apiUrl, tables) {
  let currentData = [];
  let filteredData = [];
  let currentPage = 1;
  let itemsPerPage = 20;
  let selectedLogId = null;

  const tbody = container.querySelector("#log-table-body");
  const resultCount = container.querySelector("#result-count");
  const detailSection = container.querySelector("#detail-section");
  const detailContent = container.querySelector("#detail-content");
  const pageInfo = container.querySelector("#page-info");
  const btnPrev = container.querySelector("#btn-prev");
  const btnNext = container.querySelector("#btn-next");

  // ユーザー名マップを作成
  const userMap = {};
  if (tables[0]) {
    tables[0].records.forEach(user => {
      userMap[user.ユーザーID] = user.氏名;
    });
  }

  function formatDateTime(dateStr) {
    if (!dateStr) return "";
    const date = new Date(dateStr);
    return date.toLocaleString('ja-JP', {
      year: 'numeric',
      month: '2-digit',
      day: '2-digit',
      hour: '2-digit',
      minute: '2-digit'
    });
  }

  function getStatusBadgeStyle(status) {
    switch (status) {
      case "未確認":
        return "background: rgba(255, 107, 107, 0.2); color: #ff6b6b; padding: 2px 6px; border-radius: 4px; font-size: 11px;";
      case "確認済み":
        return "background: rgba(255, 193, 7, 0.2); color: #ffc107; padding: 2px 6px; border-radius: 4px; font-size: 11px;";
      case "対応済み":
        return "background: rgba(40, 167, 69, 0.2); color: #28a745; padding: 2px 6px; border-radius: 4px; font-size: 11px;";
      default:
        return "background: rgba(108, 117, 125, 0.2); color: #6c757d; padding: 2px 6px; border-radius: 4px; font-size: 11px;";
    }
  }

  function getPriorityBadgeStyle(priority) {
    switch (priority) {
      case "高":
        return "background: rgba(220, 53, 69, 0.2); color: #dc3545; padding: 2px 6px; border-radius: 4px; font-size: 11px;";
      case "中":
        return "background: rgba(255, 193, 7, 0.2); color: #ffc107; padding: 2px 6px; border-radius: 4px; font-size: 11px;";
      case "低":
        return "background: rgba(40, 167, 69, 0.2); color: #28a745; padding: 2px 6px; border-radius: 4px; font-size: 11px;";
      default:
        return "background: rgba(108, 117, 125, 0.2); color: #6c757d; padding: 2px 6px; border-radius: 4px; font-size: 11px;";
    }
  }

  function renderRows(rows) {
    const startIndex = (currentPage - 1) * itemsPerPage;
    const endIndex = startIndex + itemsPerPage;
    const pageRows = rows.slice(startIndex, endIndex);

    tbody.innerHTML = pageRows.map(row => `
      <tr data-id="${row.異常値検出ログID}" style="cursor: pointer;">
        <td style="padding: 6px 10px; font-size: 13px;">${formatDateTime(row.検出日時)}</td>
        <td style="padding: 6px 10px; font-size: 13px;">${userMap[row.ユーザーID] || "不明"}</td>
        <td style="padding: 6px 10px; font-size: 13px;">${row.異常値種別 || ""}</td>
        <td style="padding: 6px 10px; font-size: 13px;">${row.検出項目 || ""}</td>
        <td style="padding: 6px 10px; font-size: 13px;">${row.検出値 || ""}</td>
        <td style="padding: 6px 10px; font-size: 13px;">${row.閾値 || ""}</td>
        <td style="padding: 6px 10px; font-size: 13px;"><span style="${getPriorityBadgeStyle(row.重要度)}">${row.重要度 || ""}</span></td>
        <td style="padding: 6px 10px; font-size: 13px;"><span style="${getStatusBadgeStyle(row.確認状況)}">${row.確認状況 || ""}</span></td>
        <td style="padding: 6px 10px; font-size: 13px;">
          <button class="action-btn secondary detail-btn" data-id="${row.異常値検出ログID}" style="background: transparent; color: var(--text); border: 1px solid rgba(255,255,255,0.18); padding: 4px 8px; border-radius: 4px; font-size: 11px; cursor: pointer;">詳細</button>
        </td>
      </tr>
    `).join("");

    resultCount.textContent = `${rows.length}件`;
    updatePagination(rows.length);
  }

  function updatePagination(totalItems) {
    const totalPages = Math.ceil(totalItems / itemsPerPage);
    pageInfo.textContent = `${currentPage} / ${totalPages}`;
    btnPrev.disabled = currentPage <= 1;
    btnNext.disabled = currentPage >= totalPages;
  }

  function showDetail(logId) {
    const log = currentData.find(l => l.異常値検出ログID === logId);
    if (!log) return;

    selectedLogId = logId;
    detailContent.innerHTML = `
      <div style="margin-bottom: 8px;"><strong>検出対象:</strong> ${log.検出対象テーブル || ""}</div>
      <div style="margin-bottom: 8px;"><strong>異常値種別:</strong> ${log.異常値種別 || ""}</div>
      <div style="margin-bottom: 8px;"><strong>検出項目:</strong> ${log.検出項目 || ""}</div>
      <div style="margin-bottom: 8px;"><strong>検出値:</strong> ${log.検出値 || ""} / <strong>閾値:</strong> ${log.閾値 || ""}</div>
      <div style="margin-bottom: 8px;"><strong>重要度:</strong> <span style="${getPriorityBadgeStyle(log.重要度)}">${log.重要度 || ""}</span></div>
      <div style="margin-bottom: 8px;"><strong>検出日時:</strong> ${formatDateTime(log.検出日時)}</div>
      <div style="margin-bottom: 8px;"><strong>確認者:</strong> ${log.確認者ID ? userMap[log.確認者ID] || "不明" : "未確認"}</div>
      <div><strong>対応メモ:</strong> ${log.対応メモ || "なし"}</div>
    `;

    container.querySelector("#status-update").value = log.確認状況 || "未確認";
    container.querySelector("#comment-input").value = log.対応メモ || "";
    detailSection.classList.remove("hidden");
  }

  function applyFilters() {
    const startDate = container.querySelector("#filter-start-date").value;
    const endDate = container.querySelector("#filter-end-date").value;
    const anomalyType = container.querySelector("#filter-anomaly-type").value;
    const workerName = container.querySelector("#filter-worker-name").value.toLowerCase();
    const workItem = container.querySelector("#filter-work-item").value;
    const status = container.querySelector("#filter-status").value;

    filteredData = currentData.filter(row => {
      // 日付フィルター
      if (startDate && row.検出日時 && new Date(row.検出日時) < new Date(startDate)) return false;
      if (endDate && row.検出日時 && new Date(row.検出日時) > new Date(endDate)) return false;

      // 異常値タイプフィルター
      if (anomalyType && row.異常値種別 !== anomalyType) return false;

      // 作業員名フィルター
      if (workerName) {
        const userName = userMap[row.ユーザーID] || "";
        if (!userName.toLowerCase().includes(workerName)) return false;
      }

      // 作業項目フィルター（検出項目で判定）
      if (workItem && row.検出項目 && !row.検出項目.includes(workItem)) return false;

      // ステータスフィルター
      if (status && row.確認状況 !== status) return false;

      return true;
    });

    currentPage = 1;
    renderRows(filteredData);
  }

  function exportCSV() {
    const headers = ["検出日時", "作業員名", "異常値種別", "検出項目", "検出値", "閾値", "重要度", "確認状況", "対応メモ"];
    const csvData = [headers.join(",")];

    filteredData.forEach(row => {
      const csvRow = [
        `"${formatDateTime(row.検出日時)}"`,
        `"${userMap[row.ユーザーID] || ""}"`,
        `"${row.異常値種別 || ""}"`,
        `"${row.検出項目 || ""}"`,
        `"${row.検出値 || ""}"`,
        `"${row.閾値 || ""}"`,
        `"${row.重要度 || ""}"`,
        `"${row.確認状況 || ""}"`,
        `"${row.対応メモ || ""}"`
      ];
      csvData.push(csvRow.join(","));
    });

    const csvContent = "\uFEFF" + csvData.join("\n");
    const blob = new Blob([csvContent], { type: "text/csv;charset=utf-8;" });
    const link = document.createElement("a");
    link.href = URL.createObjectURL(blob);
    link.download = `異常値検出ログ_${new Date().toISOString().slice(0, 10)}.csv`;
    link.click();
  }

  // 初期データ読み込み
  window.aivicApi.list(4).then(rows => {
    if (rows) {
      currentData = rows;
      filteredData = rows;
      renderRows(filteredData);
    }
  });

  // 検索ボタン
  container.querySelector("#btn-search").addEventListener("click", applyFilters);

  // フィルタークリアボタン
  container.querySelector("#btn-clear-filter").addEventListener("click", () => {
    container.querySelector("#filter-start-date").value = "";
    container.querySelector("#filter-end-date").value = "";
    container.querySelector("#filter-anomaly-type").value = "";
    container.querySelector("#filter-worker-name").value = "";
    container.querySelector("#filter-work-item").value = "";
    container.querySelector("#filter-status").value = "";
    filteredData = currentData;
    currentPage = 1;
    renderRows(filteredData);
  });

  // エクスポートボタン
  container.querySelector("#btn-export").addEventListener("click", exportCSV);

  // 対応状況更新ボタン
  container.querySelector("#btn-update-status").addEventListener("click", async () => {
    if (!selectedLogId) return;

    const newStatus = container.querySelector("#status-update").value;
    const comment = container.querySelector("#comment-input").value;

    if (comment.length > 1000) {
      alert("コメントは1000文字以内で入力してください。");
      return;
    }

    try {
      const updated = await window.aivicApi.update(4, selectedLogId, {
        確認状況: newStatus,
        対応メモ: comment,
        確認日時: new Date().toISOString()
      });

      if (updated) {
        // データを再読み込み
        const rows = await window.aivicApi.list(4);
        if (rows) {
          currentData = rows;
          applyFilters();
          showDetail(selectedLogId);
        }
        alert("対応状況を更新しました。");
      }
    } catch (error) {
      alert("ネットワークエラーが発生しました。再度お試しください。");
    }
  });

  // 詳細を閉じるボタン
  container.querySelector("#btn-close-detail").addEventListener("click", () => {
    detailSection.classList.add("hidden");
    selectedLogId = null;
  });

  // ページネーション
  btnPrev.addEventListener("click", () => {
    if (currentPage > 1) {
      currentPage--;
      renderRows(filteredData);
    }
  });

  btnNext.addEventListener("click", () => {
    const totalPages = Math.ceil(filteredData.length / itemsPerPage);
    if (currentPage < totalPages) {
      currentPage++;
      renderRows(filteredData);
    }
  });

  // イベントデリゲーション
  container.addEventListener("click", (e) => {
    const detailBtn = e.target.closest(".detail-btn");
    if (detailBtn) {
      showDetail(detailBtn.dataset.id);
      return;
    }

    const row = e.target.closest("tr[data-id]");
    if (row && !e.target.closest("button")) {
      showDetail(row.dataset.id);
    }
  });

  // Enterキーでの検索
  container.addEventListener("keypress", (e) => {
    if (e.key === "Enter" && e.target.matches("input")) {
      applyFilters();
    }
  });
}

function(container, apiUrl, tables) {
  let currentUser = { id: 'user-001', name: '田中太郎' };
  let activeWorks = [];
  let pausedWorks = [];
  let workItems = [];
  let confirmCallback = null;

  // 現在日時更新
  function updateDateTime() {
    const now = new Date();
    const formatted = now.getFullYear() + '/' + 
      String(now.getMonth() + 1).padStart(2, '0') + '/' + 
      String(now.getDate()).padStart(2, '0') + ' ' +
      String(now.getHours()).padStart(2, '0') + ':' + 
      String(now.getMinutes()).padStart(2, '0');
    container.querySelector('#current-datetime').textContent = formatted;
  }

  // 作業項目一覧を描画
  function renderWorkItems() {
    const select = container.querySelector('#work-item-select');
    select.innerHTML = '<option value="">作業項目を選択してください</option>';
    workItems.forEach(item => {
      if (item.有効フラグ) {
        select.innerHTML += `<option value="${item.作業項目ID}">${item.作業項目名}</option>`;
      }
    });
  }

  // 進行中作業一覧を描画
  function renderActiveWorks() {
    const container_el = container.querySelector('#active-works-list');
    if (activeWorks.length === 0) {
      container_el.innerHTML = '<div style="font-size: 12px; color: var(--text-muted); text-align: center; padding: 16px;">進行中の作業はありません</div>';
      return;
    }

    container_el.innerHTML = activeWorks.map(work => {
      const startTime = new Date(work.作業開始時刻);
      const elapsed = Math.floor((Date.now() - startTime.getTime()) / 60000);
      const hours = Math.floor(elapsed / 60);
      const minutes = elapsed % 60;

      return `
        <div style="display: flex; justify-content: space-between; align-items: center; padding: 8px; border: 1px solid rgba(255,255,255,0.1); border-radius: 4px; margin-bottom: 6px;">
          <div>
            <div style="font-size: 13px; color: var(--text); font-weight: 500;">${work.作業項目名 || '不明な作業'}</div>
            <div style="font-size: 11px; color: var(--text-muted);">開始: ${startTime.getHours().toString().padStart(2,'0')}:${startTime.getMinutes().toString().padStart(2,'0')} | 経過: ${hours}時間${minutes}分</div>
            ${work.作業場所 ? `<div style="font-size: 11px; color: var(--text-muted);">場所: ${work.作業場所}</div>` : ''}
          </div>
          <button class="action-btn secondary pause-work-btn" data-id="${work.作業記録ID}" style="padding: 4px 8px; font-size: 11px;">中断</button>
        </div>
      `;
    }).join('');
  }

  // 中断中作業一覧を描画
  function renderPausedWorks() {
    const container_el = container.querySelector('#paused-works-list');
    if (pausedWorks.length === 0) {
      container_el.innerHTML = '<div style="font-size: 12px; color: var(--text-muted); text-align: center; padding: 16px;">中断中の作業はありません</div>';
      return;
    }

    container_el.innerHTML = pausedWorks.map(work => {
      const startTime = new Date(work.作業開始時刻);

      return `
        <div style="display: flex; justify-content: space-between; align-items: center; padding: 8px; border: 1px solid rgba(255,255,255,0.1); border-radius: 4px; margin-bottom: 6px;">
          <div>
            <div style="font-size: 13px; color: var(--text); font-weight: 500;">${work.作業項目名 || '不明な作業'}</div>
            <div style="font-size: 11px; color: var(--text-muted);">開始: ${startTime.getHours().toString().padStart(2,'0')}:${startTime.getMinutes().toString().padStart(2,'0')}</div>
            ${work.作業場所 ? `<div style="font-size: 11px; color: var(--text-muted);">場所: ${work.作業場所}</div>` : ''}
          </div>
          <button class="action-btn resume-work-btn" data-id="${work.作業記録ID}" style="padding: 4px 8px; font-size: 11px;">再開</button>
        </div>
      `;
    }).join('');
  }

  // エラーメッセージ表示
  function showError(message) {
    const errorEl = container.querySelector('#error-message');
    errorEl.textContent = message;
    errorEl.style.display = 'block';
    setTimeout(() => {
      errorEl.style.display = 'none';
    }, 5000);
  }

  // 確認ダイアログ表示
  function showConfirmDialog(title, message, callback) {
    const dialog = container.querySelector('#confirm-dialog');
    container.querySelector('#dialog-title').textContent = title;
    container.querySelector('#dialog-message').textContent = message;
    dialog.classList.remove('hidden');
    confirmCallback = callback;
  }

  // データ読み込み
  async function loadData() {
    try {
      // 作業項目マスタ読み込み
      const workItemsData = await window.aivicApi.list(3);
      if (workItemsData) {
        workItems = workItemsData;
        renderWorkItems();
      }

      // 作業記録読み込み
      const workRecords = await window.aivicApi.list(1);
      if (workRecords) {
        activeWorks = workRecords.filter(w => w.作業員ID === currentUser.id && w.進捗状況 === '作業中');
        pausedWorks = workRecords.filter(w => w.作業員ID === currentUser.id && w.進捗状況 === '中断');

        // 作業項目名を補完
        activeWorks.forEach(work => {
          const item = workItems.find(i => i.作業項目ID === work.作業項目ID);
          if (item) work.作業項目名 = item.作業項目名;
        });
        pausedWorks.forEach(work => {
          const item = workItems.find(i => i.作業項目ID === work.作業項目ID);
          if (item) work.作業項目名 = item.作業項目名;
        });

        renderActiveWorks();
        renderPausedWorks();
      }
    } catch (error) {
      console.error('データ読み込みエラー:', error);
    }
  }

  // 初期データ設定
  if (tables && tables.length > 0) {
    if (tables[3] && tables[3].records) {
      workItems = tables[3].records;
      renderWorkItems();
    }
    if (tables[1] && tables[1].records) {
      const workRecords = tables[1].records;
      activeWorks = workRecords.filter(w => w.作業員ID === currentUser.id && w.進捗状況 === '作業中');
      pausedWorks = workRecords.filter(w => w.作業員ID === currentUser.id && w.進捗状況 === '中断');

      activeWorks.forEach(work => {
        const item = workItems.find(i => i.作業項目ID === work.作業項目ID);
        if (item) work.作業項目名 = item.作業項目名;
      });
      pausedWorks.forEach(work => {
        const item = workItems.find(i => i.作業項目ID === work.作業項目ID);
        if (item) work.作業項目名 = item.作業項目名;
      });

      renderActiveWorks();
      renderPausedWorks();
    }
  }

  // 最新データ読み込み
  loadData();

  // 現在日時更新開始
  updateDateTime();
  setInterval(updateDateTime, 60000);

  // 備考文字数カウント
  const memoTextarea = container.querySelector('#work-memo');
  const memoCount = container.querySelector('#memo-count');
  memoTextarea.addEventListener('input', () => {
    memoCount.textContent = memoTextarea.value.length;
  });

  // 記録開始ボタン
  container.querySelector('#btn-start-work').addEventListener('click', async () => {
    const workItemId = container.querySelector('#work-item-select').value;
    const location = container.querySelector('#work-location').value.trim();
    const memo = container.querySelector('#work-memo').value.trim();

    // バリデーション
    if (!workItemId) {
      showError('作業項目を選択してください');
      return;
    }

    // 複数作業同時開始制御
    if (activeWorks.length > 0) {
      showError('既に実行中の作業があります。同時に複数の作業を開始することはできません。');
      return;
    }

    // 作業場所の不正文字チェック
    if (location && /<script|javascript:|on\w+=/i.test(location)) {
      showError('作業場所に不正な文字が含まれています');
      return;
    }

    const selectedItem = workItems.find(item => item.作業項目ID === workItemId);
    if (!selectedItem) {
      showError('選択された作業項目が見つかりません');
      return;
    }

    try {
      const newWork = {
        作業員ID: currentUser.id,
        作業日: new Date().toISOString(),
        作業開始時刻: new Date().toISOString(),
        作業終了時刻: null,
        作業時間: null,
        プロジェクト名: selectedItem.作業項目名,
        作業場所: location || '',
        作業種別: selectedItem.カテゴリ || '一般作業',
        作業内容: memo || '',
        進捗状況: '作業中',
        備考: memo || '',
        承認状態: '未承認',
        承認者ID: null,
        承認日時: null,
        作成者ID: currentUser.id,
        作業項目ID: workItemId
      };

      const saved = await window.aivicApi.save(1, newWork);
      if (saved) {
        // フォームクリア
        container.querySelector('#work-item-select').value = '';
        container.querySelector('#work-location').value = '';
        container.querySelector('#work-memo').value = '';
        memoCount.textContent = '0';

        // データ再読み込み
        await loadData();

        // 工数入力画面に遷移
        window.showScreen("scr-1778907296658");
      }
    } catch (error) {
      showError('工数記録の開始に失敗しました');
    }
  });

  // フォームクリアボタン
  container.querySelector('#btn-clear-form').addEventListener('click', () => {
    container.querySelector('#work-item-select').value = '';
    container.querySelector('#work-location').value = '';
    container.querySelector('#work-memo').value = '';
    memoCount.textContent = '0';
  });

  // 中断作業再開
  container.addEventListener('click', async (e) => {
    const resumeBtn = e.target.closest('.resume-work-btn');
    if (resumeBtn) {
      const workId = resumeBtn.dataset.id;
      const work = pausedWorks.find(w => w.作業記録ID === workId);

      if (!work) {
        showError('指定された作業が見つかりません');
        return;
      }

      // 複数作業同時開始制御
      if (activeWorks.length > 0) {
        showError('既に実行中の作業があります。同時に複数の作業を開始することはできません。');
        return;
      }

      showConfirmDialog('作業再開確認', `「${work.作業項目名 || work.プロジェクト名}」の作業を再開しますか？`, async () => {
        try {
          const updated = await window.aivicApi.update(1, workId, {
            進捗状況: '作業中',
            作業開始時刻: new Date().toISOString()
          });

          if (updated) {
            await loadData();
          }
        } catch (error) {
          showError('作業の再開に失敗しました');
        }
      });
    }

    // 作業中断
    const pauseBtn = e.target.closest('.pause-work-btn');
    if (pauseBtn) {
      const workId = pauseBtn.dataset.id;
      const work = activeWorks.find(w => w.作業記録ID === workId);

      if (!work) {
        showError('指定された作業が見つかりません');
        return;
      }

      showConfirmDialog('作業中断確認', `「${work.作業項目名 || work.プロジェクト名}」の作業を中断しますか？`, async () => {
        try {
          const updated = await window.aivicApi.update(1, workId, {
            進捗状況: '中断'
          });

          if (updated) {
            await loadData();
          }
        } catch (error) {
          showError('作業の中断に失敗しました');
        }
      });
    }
  });

  // 確認ダイアログのイベント
  container.querySelector('#dialog-confirm').addEventListener('click', () => {
    container.querySelector('#confirm-dialog').classList.add('hidden');
    if (confirmCallback) {
      confirmCallback();
      confirmCallback = null;
    }
  });

  container.querySelector('#dialog-cancel').addEventListener('click', () => {
    container.querySelector('#confirm-dialog').classList.add('hidden');
    confirmCallback = null;
  });

  // ログアウトボタン
  container.querySelector('#btn-logout').addEventListener('click', () => {
    showConfirmDialog('ログアウト確認', 'ログアウトしますか？', () => {
      window.location.href = './login.html';
    });
  });

  // 設定メニューボタン
  container.querySelector('#btn-settings').addEventListener('click', () => {
    // 設定画面への遷移（実装時に適切な画面IDに変更）
    alert('設定画面は未実装です');
  });

  // 工数入力画面遷移
  container.querySelector('#btn-work-input').addEventListener('click', () => {
    window.showScreen("scr-1778907296658");
  });
}

function(container, apiUrl, tables) {
  // 現在の作業記録データを取得（最新の未完了記録を想定）
  let currentWorkRecord = null;

  // 初期データの設定
  async function initializeData() {
    try {
      const workRecords = await window.aivicApi.list(1); // 作業記録テーブル
      if (workRecords && workRecords.length > 0) {
        // 最新の未完了記録を取得
        currentWorkRecord = workRecords.find(r => !r.作業終了時刻) || workRecords[workRecords.length - 1];

        if (currentWorkRecord) {
          // 作業項目名の設定
          const workItems = await window.aivicApi.list(3); // 作業項目マスタ
          const workItem = workItems?.find(item => item.作業項目ID === currentWorkRecord.作業項目ID);
          if (workItem) {
            container.querySelector('#work-item-name').textContent = workItem.作業項目名;
          }

          // 開始時刻の設定
          if (currentWorkRecord.作業開始時刻) {
            const startTime = new Date(currentWorkRecord.作業開始時刻);
            container.querySelector('#start-time').textContent = 
              startTime.getHours().toString().padStart(2, '0') + ':' + 
              startTime.getMinutes().toString().padStart(2, '0');
          }

          // 終了時刻の設定（現在時刻）
          const endTime = new Date();
          container.querySelector('#end-time').textContent = 
            endTime.getHours().toString().padStart(2, '0') + ':' + 
            endTime.getMinutes().toString().padStart(2, '0');

          // 時間計算
          calculateWorkTime();
        }
      }
    } catch (error) {
      console.error('データ初期化エラー:', error);
    }
  }

  // 作業時間計算
  function calculateWorkTime() {
    if (!currentWorkRecord || !currentWorkRecord.作業開始時刻) return;

    const startTime = new Date(currentWorkRecord.作業開始時刻);
    const endTime = new Date();
    const totalMinutes = Math.floor((endTime - startTime) / (1000 * 60));

    // 中断時間の取得
    let breakMinutes = 0;
    // 実際の実装では中断記録テーブルから取得

    const actualMinutes = totalMinutes - breakMinutes;

    // 表示更新
    container.querySelector('#total-time').textContent = formatTime(totalMinutes);
    container.querySelector('#break-time').textContent = formatTime(breakMinutes);
    container.querySelector('#actual-work-time').textContent = formatTime(actualMinutes);
  }

  // 時間フォーマット（分 → HH:MM）
  function formatTime(minutes) {
    const hours = Math.floor(minutes / 60);
    const mins = minutes % 60;
    return hours.toString().padStart(2, '0') + ':' + mins.toString().padStart(2, '0');
  }

  // 文字数カウント
  function setupCharacterCount(textareaId, countId, maxLength) {
    const textarea = container.querySelector(`#${textareaId}`);
    const counter = container.querySelector(`#${countId}`);

    textarea.addEventListener('input', function() {
      const length = this.value.length;
      counter.textContent = length;

      if (length > maxLength) {
        counter.style.color = '#ff6a6a';
        this.style.borderColor = '#ff6a6a';
      } else {
        counter.style.color = 'var(--text-muted)';
        this.style.borderColor = 'rgba(255,255,255,0.18)';
      }
    });
  }

  // 異常報告チェックボックスの制御
  function setupIssueReporting() {
    const hasIssueCheckbox = container.querySelector('#has-issue');
    const issueSection = container.querySelector('#issue-content-section');
    const issueContent = container.querySelector('#issue-content');

    hasIssueCheckbox.addEventListener('change', function() {
      if (this.checked) {
        issueSection.style.display = 'block';
      } else {
        issueSection.style.display = 'none';
        issueContent.value = '';
        container.querySelector('#issue-count').textContent = '0';
      }
    });
  }

  // エラーメッセージ表示
  function showError(message) {
    const errorDiv = container.querySelector('#error-message');
    errorDiv.textContent = message;
    errorDiv.style.display = 'block';
    setTimeout(() => {
      errorDiv.style.display = 'none';
    }, 5000);
  }

  // バリデーション
  function validateForm() {
    const completionStatus = container.querySelector('#completion-status').value;
    const hasIssue = container.querySelector('#has-issue').checked;
    const issueContent = container.querySelector('#issue-content').value.trim();
    const workMemo = container.querySelector('#work-memo').value;
    const issueContentValue = container.querySelector('#issue-content').value;

    if (!completionStatus) {
      showError('完了状況を選択してください。');
      return false;
    }

    if (hasIssue && !issueContent) {
      showError('異常報告にチェックを入れた場合は、異常内容を入力してください。');
      return false;
    }

    if (workMemo.length > 1000) {
      showError('作業メモは1000文字以内で入力してください。');
      return false;
    }

    if (issueContentValue.length > 500) {
      showError('異常内容は500文字以内で入力してください。');
      return false;
    }

    return true;
  }

  // 記録確定処理
  async function confirmRecord() {
    if (!validateForm()) return;

    if (!currentWorkRecord) {
      showError('作業記録が見つかりません。');
      return;
    }

    try {
      const endTime = new Date();
      const workMemo = container.querySelector('#work-memo').value.trim();
      const completionStatus = container.querySelector('#completion-status').value;
      const hasIssue = container.querySelector('#has-issue').checked;
      const issueContent = container.querySelector('#issue-content').value.trim();

      // 作業記録の更新
      const updatedRecord = await window.aivicApi.update(1, currentWorkRecord.作業記録ID, {
        作業終了時刻: endTime.toISOString(),
        作業時間: Math.floor((endTime - new Date(currentWorkRecord.作業開始時刻)) / (1000 * 60)),
        備考: workMemo,
        進捗状況: completionStatus,
        承認状態: '未承認'
      });

      if (!updatedRecord) {
        showError('記録の保存に失敗しました。');
        return;
      }

      // 異常報告がある場合は異常値検出ログに記録
      if (hasIssue && issueContent) {
        await window.aivicApi.save(4, {
          検出対象テーブル: '作業記録',
          検出対象レコードID: currentWorkRecord.作業記録ID,
          ユーザーID: currentWorkRecord.作業員ID,
          異常値種別: '作業員報告',
          検出項目: '異常・問題報告',
          検出値: issueContent,
          閾値: '報告あり',
          重要度: '中',
          確認状況: '未確認',
          通知送信フラグ: true,
          検出日時: new Date().toISOString()
        });
      }

      alert('工数記録を確定しました。');

      // 記録確認画面に遷移
      window.showScreen("scr-1778907226171");

    } catch (error) {
      console.error('記録確定エラー:', error);
      showError('記録の確定中にエラーが発生しました。');
    }
  }

  // イベントリスナーの設定
  function setupEventListeners() {
    // 文字数カウント
    setupCharacterCount('work-memo', 'memo-count', 1000);
    setupCharacterCount('issue-content', 'issue-count', 500);

    // 異常報告制御
    setupIssueReporting();

    // ボタンイベント
    container.querySelector('#btn-confirm').addEventListener('click', confirmRecord);

    container.querySelector('#btn-cancel').addEventListener('click', function() {
      if (confirm('入力内容が失われますが、キャンセルしますか？')) {
        history.back();
      }
    });

    container.querySelector('#btn-record-check').addEventListener('click', function() {
      window.showScreen("scr-1778907226171");
    });

    // ボタンホバー効果
    const primaryBtn = container.querySelector('#btn-confirm');
    primaryBtn.addEventListener('mouseenter', function() {
      this.style.background = 'var(--primary-hover)';
    });
    primaryBtn.addEventListener('mouseleave', function() {
      this.style.background = 'var(--primary)';
    });

    const secondaryBtns = container.querySelectorAll('.action-btn.secondary');
    secondaryBtns.forEach(btn => {
      btn.addEventListener('mouseenter', function() {
        this.style.background = 'rgba(255,255,255,0.05)';
      });
      btn.addEventListener('mouseleave', function() {
        this.style.background = 'transparent';
      });
    });
  }

  // 初期化実行
  initializeData();
  setupEventListeners();
}

function(container, apiUrl, tables) {
  let autoSaveInterval = 30; // 秒
  let autoSaveTimer = null;
  let isOnline = navigator.onLine;
  let localData = JSON.parse(localStorage.getItem('workRecords') || '[]');
  let pendingSyncCount = localData.filter(item => !item.synced).length;

  // ローカルデータ再描画関数
  function renderLocalData(data = localData) {
    const tbody = container.querySelector('#local-data-tbody');
    if (!data || data.length === 0) {
      tbody.innerHTML = '<tr><td colspan="5" style="padding: 20px; text-align: center; color: var(--text-muted); font-size: 13px;">ローカルデータがありません</td></tr>';
      return;
    }

    tbody.innerHTML = data.map(item => `
      <tr data-id="${item.id}" style="border-bottom: 1px solid rgba(255,255,255,0.02);">
        <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${item.作業日 || ''}</td>
        <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${item.プロジェクト名 || ''}</td>
        <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${(item.作業内容 || '').substring(0, 30)}${(item.作業内容 || '').length > 30 ? '...' : ''}</td>
        <td style="padding: 6px 10px; font-size: 13px;">
          <span style="padding: 2px 6px; border-radius: 4px; font-size: 11px; ${item.synced ? 'background: rgba(34, 197, 94, 0.2); color: #22c55e;' : 'background: rgba(239, 68, 68, 0.2); color: #ef4444;'}">
            ${item.synced ? '同期済み' : '未同期'}
          </span>
        </td>
        <td style="padding: 6px 10px;">
          <button class="action-btn secondary delete-local-btn" data-id="${item.id}" style="background: transparent; color: var(--text); border: 1px solid rgba(255,255,255,0.18); padding: 4px 8px; border-radius: 4px; font-size: 11px; cursor: pointer;">削除</button>
        </td>
      </tr>
    `).join('');
  }

  // ステータス更新関数
  function updateStatus() {
    const autoSaveIndicator = container.querySelector('#auto-save-indicator');
    const autoSaveStatus = container.querySelector('#auto-save-status');
    const networkIndicator = container.querySelector('#network-indicator');
    const networkStatus = container.querySelector('#network-status');
    const pendingCount = container.querySelector('#pending-sync-count');
    const lastSaveTime = container.querySelector('#last-save-time');

    // ネットワーク状態
    isOnline = navigator.onLine;
    networkIndicator.style.background = isOnline ? '#22c55e' : '#ef4444';
    networkStatus.textContent = isOnline ? 'オンライン' : 'オフライン';

    // 同期待ち件数
    pendingSyncCount = localData.filter(item => !item.synced).length;
    pendingCount.textContent = `${pendingSyncCount}件`;
    if (pendingSyncCount > 100) {
      pendingCount.style.color = '#ef4444';
      showError('同期待ち件数が上限（100件）に達しています。手動同期を実行してください。');
    }

    // 自動保存状態
    autoSaveIndicator.style.background = autoSaveTimer ? '#22c55e' : '#ef4444';
    autoSaveStatus.textContent = autoSaveTimer ? '正常動作中' : '停止中';

    // 最終保存時刻
    const lastSave = localStorage.getItem('lastAutoSave');
    if (lastSave) {
      lastSaveTime.textContent = new Date(lastSave).toLocaleString('ja-JP');
    }
  }

  // エラー表示関数
  function showError(message) {
    const errorNotification = container.querySelector('#error-notification');
    const errorMessage = container.querySelector('#error-message');
    errorMessage.textContent = message;
    errorNotification.classList.remove('hidden');
    setTimeout(() => {
      errorNotification.classList.add('hidden');
    }, 5000);
  }

  // 自動保存開始
  function startAutoSave() {
    if (autoSaveTimer) clearInterval(autoSaveTimer);

    autoSaveTimer = setInterval(async () => {
      try {
        // 未同期データがある場合のみ自動保存実行
        const unsyncedData = localData.filter(item => !item.synced);
        if (unsyncedData.length > 0 && isOnline) {
          await performSync();
        }
        localStorage.setItem('lastAutoSave', new Date().toISOString());
        updateStatus();
      } catch (error) {
        console.error('Auto save error:', error);
        showError('自動保存中にエラーが発生しました');
      }
    }, autoSaveInterval * 1000);

    updateStatus();
  }

  // 同期実行
  async function performSync() {
    const unsyncedData = localData.filter(item => !item.synced);
    let successCount = 0;
    let failCount = 0;

    for (const item of unsyncedData) {
      try {
        const saved = await window.aivicApi.save(1, {
          作業員ID: item.作業員ID,
          作業日: item.作業日,
          作業開始時刻: item.作業開始時刻,
          作業終了時刻: item.作業終了時刻,
          作業時間: item.作業時間,
          プロジェクト名: item.プロジェクト名,
          作業場所: item.作業場所,
          作業種別: item.作業種別,
          作業内容: item.作業内容,
          進捗状況: item.進捗状況,
          備考: item.備考,
          承認状態: '未承認',
          作成者ID: item.作業員ID
        });

        if (saved) {
          // ローカルデータを同期済みにマーク
          const localIndex = localData.findIndex(local => local.id === item.id);
          if (localIndex !== -1) {
            localData[localIndex].synced = true;
          }
          successCount++;
        } else {
          failCount++;
        }
      } catch (error) {
        console.error('Sync error for item:', item.id, error);
        failCount++;
      }
    }

    // ローカルストレージ更新
    localStorage.setItem('workRecords', JSON.stringify(localData));

    if (failCount > 0) {
      showError(`同期完了: 成功${successCount}件、失敗${failCount}件`);
    }

    renderLocalData();
    updateStatus();
  }

  // 初期データ描画
  renderLocalData();
  updateStatus();
  startAutoSave();

  // ネットワーク状態監視
  window.addEventListener('online', () => {
    isOnline = true;
    updateStatus();
    // オンライン復旧時に自動同期
    if (pendingSyncCount > 0) {
      setTimeout(() => performSync(), 1000);
    }
  });

  window.addEventListener('offline', () => {
    isOnline = false;
    updateStatus();
  });

  // 保存間隔更新
  container.querySelector('#btn-update-interval').addEventListener('click', () => {
    const intervalInput = container.querySelector('#save-interval');
    const newInterval = parseInt(intervalInput.value);

    if (newInterval < 1) {
      showError('保存間隔は1秒以上で設定してください');
      intervalInput.value = autoSaveInterval;
      return;
    }

    if (newInterval > 86400) {
      showError('保存間隔は86400秒以下で設定してください');
      intervalInput.value = autoSaveInterval;
      return;
    }

    autoSaveInterval = newInterval;
    localStorage.setItem('autoSaveInterval', autoSaveInterval.toString());
    startAutoSave(); // 新しい間隔で再開

    // 成功通知（簡易）
    const btn = container.querySelector('#btn-update-interval');
    const originalText = btn.textContent;
    btn.textContent = '更新完了';
    btn.style.background = 'var(--primary)';
    btn.style.color = '#fff';
    setTimeout(() => {
      btn.textContent = originalText;
      btn.style.background = 'transparent';
      btn.style.color = 'var(--text)';
    }, 1500);
  });

  // 手動同期実行
  container.querySelector('#btn-manual-sync').addEventListener('click', async () => {
    if (!isOnline) {
      showError('ネットワークに接続されていません');
      return;
    }

    if (pendingSyncCount === 0) {
      showError('同期待ちのデータがありません');
      return;
    }

    const btn = container.querySelector('#btn-manual-sync');
    const originalText = btn.textContent;
    btn.textContent = '同期中...';
    btn.disabled = true;

    try {
      await performSync();
      btn.textContent = '同期完了';
      setTimeout(() => {
        btn.textContent = originalText;
        btn.disabled = false;
      }, 2000);
    } catch (error) {
      showError('手動同期中にエラーが発生しました');
      btn.textContent = originalText;
      btn.disabled = false;
    }
  });

  // データ復旧
  container.querySelector('#btn-restore-data').addEventListener('click', () => {
    if (!confirm('ローカルに保存されたデータを復旧しますか？')) return;

    // 復旧処理（実際にはより複雑な処理が必要）
    const backupData = localStorage.getItem('workRecordsBackup');
    if (backupData) {
      localData = JSON.parse(backupData);
      localStorage.setItem('workRecords', JSON.stringify(localData));
      renderLocalData();
      updateStatus();

      const btn = container.querySelector('#btn-restore-data');
      const originalText = btn.textContent;
      btn.textContent = '復旧完了';
      setTimeout(() => {
        btn.textContent = originalText;
      }, 2000);
    } else {
      showError('復旧可能なデータが見つかりません');
    }
  });

  // ローカルデータ削除
  container.querySelector('#btn-clear-local').addEventListener('click', () => {
    if (!confirm('ローカルに保存されたデータをすべて削除しますか？\n※未同期のデータも削除されます')) return;

    localStorage.removeItem('workRecords');
    localData = [];
    renderLocalData();
    updateStatus();

    const btn = container.querySelector('#btn-clear-local');
    const originalText = btn.textContent;
    btn.textContent = '削除完了';
    setTimeout(() => {
      btn.textContent = originalText;
    }, 2000);
  });

  // ローカルデータ検索
  container.querySelector('#btn-search-local').addEventListener('click', () => {
    const keyword = container.querySelector('#search-local-data').value.trim();
    if (!keyword) {
      renderLocalData();
      return;
    }

    const filtered = localData.filter(item => 
      (item.作業内容 || '').includes(keyword) ||
      (item.プロジェクト名 || '').includes(keyword)
    );
    renderLocalData(filtered);
  });

  // ローカルデータ更新
  container.querySelector('#btn-refresh-local').addEventListener('click', () => {
    localData = JSON.parse(localStorage.getItem('workRecords') || '[]');
    renderLocalData();
    updateStatus();
  });

  // 工数記録画面へ戻る
  container.querySelector('#btn-back-to-records').addEventListener('click', () => {
    window.showScreen('scr-1778907133295');
  });

  // ローカルデータ個別削除
  container.addEventListener('click', (e) => {
    const deleteBtn = e.target.closest('.delete-local-btn');
    if (deleteBtn) {
      if (!confirm('このローカルデータを削除しますか？')) return;

      const itemId = deleteBtn.dataset.id;
      localData = localData.filter(item => item.id !== itemId);
      localStorage.setItem('workRecords', JSON.stringify(localData));
      renderLocalData();
      updateStatus();
    }
  });

  // 保存間隔の初期値復元
  const savedInterval = localStorage.getItem('autoSaveInterval');
  if (savedInterval) {
    autoSaveInterval = parseInt(savedInterval);
    container.querySelector('#save-interval').value = autoSaveInterval;
  }
}

function(container, apiUrl, tables) {
  const tbody = container.querySelector("#records-tbody");
  const emptyState = container.querySelector("#empty-state");
  const tableWrap = container.querySelector(".table-wrap");
  const detailModal = container.querySelector("#detail-modal");
  const detailContent = container.querySelector("#detail-content");

  let currentRecords = [];
  let breakRecords = [];
  let workItems = [];
  let anomalyLogs = [];

  // 初期データの取得
  if (tables && tables.length > 0) {
    currentRecords = tables[1]?.records || []; // 作業記録
    breakRecords = tables[2]?.records || []; // 中断記録
    workItems = tables[3]?.records || []; // 作業項目マスタ
    anomalyLogs = tables[4]?.records || []; // 異常値検出ログ
  }

  // 今日の日付を設定
  const today = new Date().toISOString().split('T')[0];
  container.querySelector("#input-date").value = today;

  // 時間フォーマット関数
  function formatTime(timestamp) {
    if (!timestamp) return '';
    const date = new Date(timestamp);
    return date.toTimeString().slice(0, 5);
  }

  // 日付フォーマット関数
  function formatDate(timestamp) {
    if (!timestamp) return '';
    const date = new Date(timestamp);
    return date.toISOString().split('T')[0];
  }

  // 作業時間計算（分）
  function calculateWorkTime(startTime, endTime) {
    if (!startTime || !endTime) return 0;
    const start = new Date(startTime);
    const end = new Date(endTime);
    return Math.floor((end - start) / (1000 * 60));
  }

  // 中断時間計算
  function calculateBreakTime(recordId) {
    const breaks = breakRecords.filter(b => b.作業記録ID === recordId);
    return breaks.reduce((total, b) => {
      if (b.中断時間) return total + b.中断時間;
      if (b.中断開始日時 && b.中断終了日時) {
        const start = new Date(b.中断開始日時);
        const end = new Date(b.中断終了日時);
        return total + Math.floor((end - start) / (1000 * 60));
      }
      return total;
    }, 0);
  }

  // 作業項目名取得
  function getWorkItemName(recordId) {
    const record = currentRecords.find(r => r.作業記録ID === recordId);
    if (!record) return '';
    const workItem = workItems.find(w => w.作業項目名 === record.作業種別);
    return workItem ? workItem.作業項目名 : record.作業種別 || '';
  }

  // 異常値チェック
  function hasAnomaly(recordId) {
    return anomalyLogs.some(log => log.検出対象レコードID === recordId && log.確認状況 === '未確認');
  }

  // 時間表示フォーマット
  function formatDuration(minutes) {
    if (!minutes || minutes === 0) return '0分';
    const hours = Math.floor(minutes / 60);
    const mins = minutes % 60;
    if (hours === 0) return `${mins}分`;
    if (mins === 0) return `${hours}時間`;
    return `${hours}時間${mins}分`;
  }

  // 再描画関数
  function renderRows(records) {
    if (!records || records.length === 0) {
      tbody.innerHTML = '';
      emptyState.classList.remove('hidden');
      tableWrap.style.display = 'none';
      return;
    }

    emptyState.classList.add('hidden');
    tableWrap.style.display = 'block';

    tbody.innerHTML = records.map(record => {
      const workTime = calculateWorkTime(record.作業開始時刻, record.作業終了時刻);
      const breakTime = calculateBreakTime(record.作業記録ID);
      const workItemName = getWorkItemName(record.作業記録ID);
      const hasAnomalyFlag = hasAnomaly(record.作業記録ID);
      const isApproved = record.承認状態 === '承認済み';

      // 異常値警告（24時間超過、終了時刻が開始時刻より早い、中断時間が作業時間を超過）
      const isAbnormalTime = workTime > 1440 || workTime < 0 || breakTime > workTime;
      const showWarning = hasAnomalyFlag || isAbnormalTime;

      return `
        <tr data-id="${record.作業記録ID}">
          <td>${formatDate(record.作業日)}</td>
          <td>
            ${workItemName}
            ${showWarning ? '<span style="color: #ff6a00; margin-left: 4px;" title="異常値が検出されました">⚠️</span>' : ''}
          </td>
          <td>${formatTime(record.作業開始時刻)}</td>
          <td>${formatTime(record.作業終了時刻)}</td>
          <td>${formatDuration(workTime)}</td>
          <td>${formatDuration(breakTime)}</td>
          <td>${record.作業場所 || ''}</td>
          <td>
            <span style="padding: 2px 6px; border-radius: 4px; font-size: 11px; 
              ${record.進捗状況 === '完了' ? 'background: rgba(34, 197, 94, 0.2); color: #22c55e;' : 
                record.進捗状況 === '作業中' ? 'background: rgba(59, 130, 246, 0.2); color: #3b82f6;' : 
                'background: rgba(156, 163, 175, 0.2); color: #9ca3af;'}">
              ${record.進捗状況}
            </span>
          </td>
          <td>
            <span style="padding: 2px 6px; border-radius: 4px; font-size: 11px;
              ${record.承認状態 === '承認済み' ? 'background: rgba(34, 197, 94, 0.2); color: #22c55e;' : 
                record.承認状態 === '差し戻し' ? 'background: rgba(239, 68, 68, 0.2); color: #ef4444;' : 
                'background: rgba(251, 191, 36, 0.2); color: #fbbf24;'}">
              ${record.承認状態}
            </span>
          </td>
          <td>
            <button class="action-btn secondary detail-btn" data-id="${record.作業記録ID}" style="margin-right: 4px;">詳細</button>
            ${!isApproved ? `<button class="action-btn secondary edit-btn" data-id="${record.作業記録ID}" style="margin-right: 4px;">修正</button>` : ''}
            ${!isApproved ? `<button class="action-btn secondary delete-btn" data-id="${record.作業記録ID}">削除</button>` : ''}
          </td>
        </tr>
      `;
    }).join('');
  }

  // 詳細表示
  function showDetail(recordId) {
    const record = currentRecords.find(r => r.作業記録ID === recordId);
    if (!record) return;

    const workTime = calculateWorkTime(record.作業開始時刻, record.作業終了時刻);
    const breakTime = calculateBreakTime(record.作業記録ID);
    const breaks = breakRecords.filter(b => b.作業記録ID === recordId);

    detailContent.innerHTML = `
      <div style="display: grid; grid-template-columns: 1fr 1fr; gap: 16px;">
        <div>
          <h4 style="font-size: 13px; font-weight: 600; color: var(--text); margin: 0 0 8px 0;">基本情報</h4>
          <div style="font-size: 13px; line-height: 1.6;">
            <div><strong>作業日:</strong> ${formatDate(record.作業日)}</div>
            <div><strong>プロジェクト:</strong> ${record.プロジェクト名 || ''}</div>
            <div><strong>作業場所:</strong> ${record.作業場所 || ''}</div>
            <div><strong>作業種別:</strong> ${record.作業種別 || ''}</div>
            <div><strong>進捗状況:</strong> ${record.進捗状況 || ''}</div>
            <div><strong>承認状態:</strong> ${record.承認状態 || ''}</div>
          </div>
        </div>
        <div>
          <h4 style="font-size: 13px; font-weight: 600; color: var(--text); margin: 0 0 8px 0;">時間情報</h4>
          <div style="font-size: 13px; line-height: 1.6;">
            <div><strong>開始時刻:</strong> ${formatTime(record.作業開始時刻)}</div>
            <div><strong>終了時刻:</strong> ${formatTime(record.作業終了時刻)}</div>
            <div><strong>作業時間:</strong> ${formatDuration(workTime)}</div>
            <div><strong>中断時間:</strong> ${formatDuration(breakTime)}</div>
            <div><strong>実働時間:</strong> ${formatDuration(workTime - breakTime)}</div>
          </div>
        </div>
      </div>

      <div style="margin-top: 16px;">
        <h4 style="font-size: 13px; font-weight: 600; color: var(--text); margin: 0 0 8px 0;">作業内容</h4>
        <div style="background: rgba(0,0,0,0.25); padding: 8px; border-radius: 6px; font-size: 13px; line-height: 1.4;">
          ${record.作業内容 || ''}
        </div>
      </div>

      ${record.備考 ? `
        <div style="margin-top: 16px;">
          <h4 style="font-size: 13px; font-weight: 600; color: var(--text); margin: 0 0 8px 0;">備考</h4>
          <div style="background: rgba(0,0,0,0.25); padding: 8px; border-radius: 6px; font-size: 13px; line-height: 1.4;">
            ${record.備考}
          </div>
        </div>
      ` : ''}

      ${breaks.length > 0 ? `
        <div style="margin-top: 16px;">
          <h4 style="font-size: 13px; font-weight: 600; color: var(--text); margin: 0 0 8px 0;">中断記録</h4>
          ${breaks.map(b => `
            <div style="background: rgba(0,0,0,0.25); padding: 8px; border-radius: 6px; margin-bottom: 8px; font-size: 13px;">
              <div><strong>中断時間:</strong> ${formatTime(b.中断開始日時)} - ${formatTime(b.中断終了日時)} (${formatDuration(b.中断時間)})</div>
              <div><strong>理由:</strong> ${b.中断理由区分} ${b.中断理由詳細 ? '- ' + b.中断理由詳細 : ''}</div>
            </div>
          `).join('')}
        </div>
      ` : ''}
    `;

    detailModal.classList.remove('hidden');
  }

  // CSVエクスポート
  function exportCSV() {
    const headers = ['日付', '作業項目', '開始時刻', '終了時刻', '作業時間', '中断時間', '作業場所', '進捗状況', '承認状態', '作業内容', '備考'];
    const csvContent = '\uFEFF' + [
      headers.join(','),
      ...currentRecords.map(record => {
        const workTime = calculateWorkTime(record.作業開始時刻, record.作業終了時刻);
        const breakTime = calculateBreakTime(record.作業記録ID);
        const workItemName = getWorkItemName(record.作業記録ID);

        return [
          formatDate(record.作業日),
          `"${workItemName}"`,
          formatTime(record.作業開始時刻),
          formatTime(record.作業終了時刻),
          formatDuration(workTime),
          formatDuration(breakTime),
          `"${record.作業場所 || ''}"`,
          record.進捗状況 || '',
          record.承認状態 || '',
          `"${record.作業内容 || ''}"`,
          `"${record.備考 || ''}"`
        ].join(',');
      })
    ].join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `work_records_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  }

  // フィルタリング
  function filterRecords() {
    const selectedDate = container.querySelector("#input-date").value;
    const startDate = container.querySelector("#input-start-date").value;
    const endDate = container.querySelector("#input-end-date").value;

    let filtered = [...currentRecords];

    if (selectedDate) {
      filtered = filtered.filter(record => {
        const recordDate = formatDate(record.作業日);
        return recordDate === selectedDate;
      });
    } else if (startDate && endDate) {
      if (startDate > endDate) {
        alert('開始日は終了日より前の日付を指定してください');
        return;
      }
      filtered = filtered.filter(record => {
        const recordDate = formatDate(record.作業日);
        return recordDate >= startDate && recordDate <= endDate;
      });
    } else if (startDate) {
      filtered = filtered.filter(record => {
        const recordDate = formatDate(record.作業日);
        return recordDate >= startDate;
      });
    } else if (endDate) {
      filtered = filtered.filter(record => {
        const recordDate = formatDate(record.作業日);
        return recordDate <= endDate;
      });
    }

    renderRows(filtered);
  }

  // 初期データ読み込み
  async function loadData() {
    try {
      const records = await window.aivicApi.list(1); // 作業記録
      if (records) {
        currentRecords = records;
        filterRecords();
      }
    } catch (error) {
      console.error('データ読み込みエラー:', error);
      renderRows(currentRecords);
    }
  }

  // イベントリスナー
  container.querySelector("#btn-menu").addEventListener("click", () => {
    window.showScreen("scr-1778907133295");
  });

  container.querySelector("#btn-filter").addEventListener("click", filterRecords);

  container.querySelector("#input-date").addEventListener("change", () => {
    // 日付選択時は期間をクリア
    container.querySelector("#input-start-date").value = '';
    container.querySelector("#input-end-date").value = '';
    filterRecords();
  });

  container.querySelector("#input-start-date").addEventListener("change", () => {
    // 期間選択時は日付をクリア
    container.querySelector("#input-date").value = '';
  });

  container.querySelector("#input-end-date").addEventListener("change", () => {
    // 期間選択時は日付をクリア
    container.querySelector("#input-date").value = '';
  });

  container.querySelector("#btn-csv-export").addEventListener("click", exportCSV);

  container.querySelector("#btn-close-modal").addEventListener("click", () => {
    detailModal.classList.add('hidden');
  });

  // イベントデリゲーション
  container.addEventListener("click", async (e) => {
    const detailBtn = e.target.closest(".detail-btn");
    const editBtn = e.target.closest(".edit-btn");
    const deleteBtn = e.target.closest(".delete-btn");

    if (detailBtn) {
      showDetail(detailBtn.dataset.id);
    }

    if (editBtn) {
      // 編集画面に遷移（記録IDをセッションストレージに保存）
      sessionStorage.setItem('editRecordId', editBtn.dataset.id);
      window.showScreen("scr-1778907343735");
    }

    if (deleteBtn) {
      if (!confirm("この記録を削除しますか？")) return;

      try {
        await window.aivicApi.delete(1, deleteBtn.dataset.id);
        await loadData(); // 削除後にデータを再読み込み
      } catch (error) {
        console.error('削除エラー:', error);
        alert('削除に失敗しました');
      }
    }
  });

  // モーダル外クリックで閉じる
  detailModal.addEventListener("click", (e) => {
    if (e.target === detailModal) {
      detailModal.classList.add('hidden');
    }
  });

  // 初期表示
  loadData();
}

function(container, apiUrl, tables) {
  let mediaRecorder = null;
  let audioChunks = [];
  let recordedBlob = null;
  let isRecording = false;

  // DOM要素の取得
  const startTimeInput = container.querySelector('#start-time');
  const endTimeInput = container.querySelector('#end-time');
  const reasonSelect = container.querySelector('#reason');
  const locationInput = container.querySelector('#location');
  const detailsTextarea = container.querySelector('#details');
  const charCount = container.querySelector('#char-count');
  const durationDiv = container.querySelector('#duration');
  const photoUpload = container.querySelector('#photo-upload');
  const photoBtn = container.querySelector('#photo-btn');
  const photoPreview = container.querySelector('#photo-preview');
  const recordBtn = container.querySelector('#record-btn');
  const playBtn = container.querySelector('#play-btn');
  const recordStatus = container.querySelector('#record-status');
  const errorMessage = container.querySelector('#error-message');
  const tempSaveBtn = container.querySelector('#temp-save-btn');
  const completeBtn = container.querySelector('#complete-btn');
  const selectAllImpact = container.querySelector('#select-all-impact');
  const impactCheckboxes = container.querySelectorAll('input[name="impact"]');

  // 現在時刻を中断開始時刻にセット
  const now = new Date();
  startTimeInput.value = now.toISOString().slice(0, 16);

  // 関連作業項目の表示（現在進行中の作業があれば表示）
  const workItemDiv = container.querySelector('#work-item');
  if (tables[1] && tables[1].records) {
    const activeWork = tables[1].records.find(r => r.進捗状況 === '作業中');
    if (activeWork) {
      workItemDiv.textContent = `${activeWork.プロジェクト名} - ${activeWork.作業種別}`;
      workItemDiv.style.color = 'var(--text)';
    }
  }

  // エラー表示関数
  function showError(message) {
    errorMessage.textContent = message;
    errorMessage.style.display = 'block';
    setTimeout(() => {
      errorMessage.style.display = 'none';
    }, 5000);
  }

  // 中断時間の自動計算
  function updateDuration() {
    const start = startTimeInput.value;
    const end = endTimeInput.value;

    if (start && end) {
      const startTime = new Date(start);
      const endTime = new Date(end);

      if (endTime > startTime) {
        const diffMs = endTime - startTime;
        const diffMinutes = Math.floor(diffMs / (1000 * 60));
        const hours = Math.floor(diffMinutes / 60);
        const minutes = diffMinutes % 60;
        durationDiv.textContent = `${hours.toString().padStart(2, '0')}:${minutes.toString().padStart(2, '0')}`;
      } else {
        durationDiv.textContent = '--:--';
      }
    } else {
      durationDiv.textContent = '--:--';
    }
  }

  // 文字数カウント
  detailsTextarea.addEventListener('input', () => {
    charCount.textContent = detailsTextarea.value.length;
  });

  // 時刻変更時の中断時間更新
  startTimeInput.addEventListener('change', updateDuration);
  endTimeInput.addEventListener('change', updateDuration);

  // 写真添付
  photoBtn.addEventListener('click', () => {
    photoUpload.click();
  });

  photoUpload.addEventListener('change', (e) => {
    const file = e.target.files[0];
    if (file) {
      // ファイルサイズチェック（10MB）
      if (file.size > 10 * 1024 * 1024) {
        showError('ファイルサイズが上限（10MB）を超えています');
        photoUpload.value = '';
        return;
      }

      // ファイル形式チェック
      if (!file.type.startsWith('image/')) {
        showError('対応していないファイル形式です。画像ファイルを選択してください');
        photoUpload.value = '';
        return;
      }

      photoPreview.textContent = `📷 ${file.name} (${(file.size / 1024).toFixed(1)}KB)`;
      photoBtn.textContent = '📷 写真を変更';
    }
  });

  // 音声録音
  recordBtn.addEventListener('click', async () => {
    if (!isRecording) {
      try {
        const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
        mediaRecorder = new MediaRecorder(stream);
        audioChunks = [];

        mediaRecorder.ondataavailable = (event) => {
          audioChunks.push(event.data);
        };

        mediaRecorder.onstop = () => {
          recordedBlob = new Blob(audioChunks, { type: 'audio/wav' });
          playBtn.disabled = false;
          playBtn.style.background = 'rgba(0,0,0,0.25)';
          playBtn.style.color = 'var(--text)';
          playBtn.style.cursor = 'pointer';
          recordStatus.textContent = `🎤 録音完了 (${(recordedBlob.size / 1024).toFixed(1)}KB)`;

          // ストリームを停止
          stream.getTracks().forEach(track => track.stop());
        };

        mediaRecorder.start();
        isRecording = true;
        recordBtn.textContent = '⏹️ 録音停止';
        recordStatus.textContent = '🔴 録音中...';

      } catch (error) {
        showError('マイクへのアクセスが拒否されました。ブラウザの設定を確認してください');
      }
    } else {
      mediaRecorder.stop();
      isRecording = false;
      recordBtn.textContent = '🎤 録音開始';
    }
  });

  // 音声再生
  playBtn.addEventListener('click', () => {
    if (recordedBlob) {
      const audio = new Audio(URL.createObjectURL(recordedBlob));
      audio.play();
    }
  });

  // 影響範囲の全選択・全解除
  selectAllImpact.addEventListener('change', () => {
    impactCheckboxes.forEach(checkbox => {
      checkbox.checked = selectAllImpact.checked;
    });
  });

  // 個別選択時の全選択チェックボックス更新
  impactCheckboxes.forEach(checkbox => {
    checkbox.addEventListener('change', () => {
      const allChecked = Array.from(impactCheckboxes).every(cb => cb.checked);
      const noneChecked = Array.from(impactCheckboxes).every(cb => !cb.checked);

      if (allChecked) {
        selectAllImpact.checked = true;
        selectAllImpact.indeterminate = false;
      } else if (noneChecked) {
        selectAllImpact.checked = false;
        selectAllImpact.indeterminate = false;
      } else {
        selectAllImpact.checked = false;
        selectAllImpact.indeterminate = true;
      }
    });
  });

  // バリデーション関数
  function validateForm() {
    const startTime = startTimeInput.value;
    const reason = reasonSelect.value;
    const details = detailsTextarea.value;

    if (!startTime) {
      showError('中断開始時刻は必須です');
      return false;
    }

    if (!reason) {
      showError('中断理由は必須です');
      return false;
    }

    // 未来時刻チェック
    const startDate = new Date(startTime);
    const now = new Date();
    if (startDate > now) {
      showError('未来の時刻は入力できません');
      return false;
    }

    // 文字数チェック
    if (details.length > 1000) {
      showError('中断詳細は1000文字以内で入力してください');
      return false;
    }

    // 終了時刻が開始時刻より前でないかチェック
    const endTime = endTimeInput.value;
    if (endTime) {
      const endDate = new Date(endTime);
      if (endDate <= startDate) {
        showError('中断終了時刻は開始時刻より後の時刻を入力してください');
        return false;
      }
    }

    return true;
  }

  // フォームデータ収集
  function collectFormData() {
    const urgencyRadio = container.querySelector('input[name="urgency"]:checked');
    const impactValues = Array.from(container.querySelectorAll('input[name="impact"]:checked'))
      .map(cb => cb.value);

    const startTime = startTimeInput.value;
    const endTime = endTimeInput.value || null;
    let duration = null;

    if (startTime && endTime) {
      const diffMs = new Date(endTime) - new Date(startTime);
      duration = Math.floor(diffMs / (1000 * 60)); // 分単位
    }

    // 関連する作業記録IDを取得
    let workRecordId = null;
    if (tables[1] && tables[1].records) {
      const activeWork = tables[1].records.find(r => r.進捗状況 === '作業中');
      if (activeWork) {
        workRecordId = activeWork.作業記録ID;
      }
    }

    return {
      中断記録ID: crypto.randomUUID(),
      作業記録ID: workRecordId,
      中断開始日時: startTime,
      中断終了日時: endTime,
      中断理由区分: reasonSelect.value,
      中断理由詳細: detailsTextarea.value || null,
      中断時間: duration,
      影響度: urgencyRadio ? urgencyRadio.value : '中',
      対応状況: '対応中',
      記録者ID: 'current-user-id', // 実際の実装では現在のユーザーIDを使用
      作成日時: new Date().toISOString(),
      更新日時: new Date().toISOString()
    };
  }

  // 一時保存
  tempSaveBtn.addEventListener('click', async () => {
    if (!validateForm()) return;

    const formData = collectFormData();

    try {
      // ローカルストレージに保存
      localStorage.setItem('interruption_temp_data', JSON.stringify(formData));

      // 成功メッセージ表示
      const successDiv = document.createElement('div');
      successDiv.style.cssText = 'padding: 8px 12px; margin-bottom: 12px; border-radius: 6px; background: rgba(34, 197, 94, 0.1); border-left: 3px solid #22c55e; color: #86efac; font-size: 13px;';
      successDiv.textContent = '一時保存しました';
      errorMessage.parentNode.insertBefore(successDiv, errorMessage);

      setTimeout(() => {
        successDiv.remove();
      }, 3000);

    } catch (error) {
      showError('一時保存に失敗しました');
    }
  });

  // 記録完了
  completeBtn.addEventListener('click', async () => {
    if (!validateForm()) return;

    const formData = collectFormData();

    try {
      const saved = await window.aivicApi.save(2, formData); // 中断記録テーブル

      if (saved) {
        // 一時保存データを削除
        localStorage.removeItem('interruption_temp_data');

        // 作業再開記録画面に遷移
        window.showScreen("scr-1778907251446");
      } else {
        showError('ネットワークに接続できません。しばらく経ってから再度お試しください');
      }
    } catch (error) {
      showError('記録の保存に失敗しました');
    }
  });

  // 一時保存データの復元
  const tempData = localStorage.getItem('interruption_temp_data');
  if (tempData) {
    try {
      const data = JSON.parse(tempData);

      if (data.中断開始日時) startTimeInput.value = data.中断開始日時.slice(0, 16);
      if (data.中断終了日時) endTimeInput.value = data.中断終了日時.slice(0, 16);
      if (data.中断理由区分) reasonSelect.value = data.中断理由区分;
      if (data.中断理由詳細) detailsTextarea.value = data.中断理由詳細;
      if (data.影響度) {
        const urgencyRadio = container.querySelector(`input[name="urgency"][value="${data.影響度}"]`);
        if (urgencyRadio) urgencyRadio.checked = true;
      }

      // 文字数更新
      charCount.textContent = detailsTextarea.value.length;

      // 中断時間更新
      updateDuration();

    } catch (error) {
      console.error('一時保存データの復元に失敗しました:', error);
    }
  }
}

function(container, apiUrl, tables) {
  let selectedWorkRecord = null;
  let selectedInterruptRecord = null;

  // 現在時刻を設定
  function setCurrentTime() {
    const now = new Date();
    const localDateTime = new Date(now.getTime() - now.getTimezoneOffset() * 60000).toISOString().slice(0, 16);
    container.querySelector("#resume-time").value = localDateTime;
  }

  // 中断中作業一覧を描画
  function renderSuspendedWorks(workRecords, interruptRecords) {
    const tbody = container.querySelector("#suspended-work-list");

    // 中断中の作業を抽出（進捗状況が「中断」で、対応する中断記録が存在する）
    const suspendedWorks = workRecords.filter(work => 
      work.進捗状況 === '中断' && 
      interruptRecords.some(interrupt => interrupt.作業記録ID === work.作業記録ID && !interrupt.中断終了日時)
    );

    if (suspendedWorks.length === 0) {
      tbody.innerHTML = `
        <tr>
          <td colspan="6" style="text-align: center; color: var(--text-muted); padding: 20px;">
            現在中断中の作業はありません
          </td>
        </tr>
      `;
      return;
    }

    tbody.innerHTML = suspendedWorks.map(work => {
      const interrupt = interruptRecords.find(i => i.作業記録ID === work.作業記録ID && !i.中断終了日時);
      const interruptDuration = interrupt ? Math.floor((new Date() - new Date(interrupt.中断開始日時)) / (1000 * 60)) : 0;

      return `
        <tr data-work-id="${work.作業記録ID}" data-interrupt-id="${interrupt?.中断記録ID || ''}" style="cursor: pointer;">
          <td>
            <input type="radio" name="selected-work" value="${work.作業記録ID}" style="accent-color: var(--primary);">
          </td>
          <td>${work.作業内容 || ''}</td>
          <td>${work.プロジェクト名 || ''}</td>
          <td>${interrupt ? new Date(interrupt.中断開始日時).toLocaleString() : ''}</td>
          <td>${interrupt?.中断理由詳細 || interrupt?.中断理由区分 || ''}</td>
          <td>${interruptDuration}分</td>
        </tr>
      `;
    }).join("");
  }

  // 作業選択時の処理
  function handleWorkSelection(workId, interruptId) {
    const workRecords = tables[1].records || [];
    const interruptRecords = tables[2].records || [];

    selectedWorkRecord = workRecords.find(w => w.作業記録ID === workId);
    selectedInterruptRecord = interruptRecords.find(i => i.中断記録ID === interruptId);

    if (selectedWorkRecord) {
      container.querySelector("#selected-work-name").value = `${selectedWorkRecord.作業内容} (${selectedWorkRecord.プロジェクト名})`;
      container.querySelector("#resume-form").classList.remove("hidden");
      setCurrentTime();
    }
  }

  // 文字数カウント更新
  function updateCharCount() {
    const textarea = container.querySelector("#resume-reason-detail");
    const counter = container.querySelector("#reason-char-count");
    counter.textContent = textarea.value.length;
  }

  // 初期データ読み込み
  async function loadInitialData() {
    try {
      const [workRecords, interruptRecords] = await Promise.all([
        window.aivicApi.list(1), // 作業記録
        window.aivicApi.list(2)  // 中断記録
      ]);

      if (workRecords && interruptRecords) {
        renderSuspendedWorks(workRecords, interruptRecords);
      } else {
        renderSuspendedWorks(tables[1].records || [], tables[2].records || []);
      }
    } catch (error) {
      console.error("データ読み込みエラー:", error);
      renderSuspendedWorks(tables[1].records || [], tables[2].records || []);
    }
  }

  // 作業再開処理
  async function resumeWork() {
    if (!selectedWorkRecord || !selectedInterruptRecord) {
      alert("作業が選択されていません");
      return;
    }

    const resumeTime = container.querySelector("#resume-time").value;
    const reasonDetail = container.querySelector("#resume-reason-detail").value.trim();
    const reasonCategory = container.querySelector("#resume-reason-category").value;

    if (!reasonDetail && !reasonCategory) {
      alert("再開理由を入力してください");
      return;
    }

    if (reasonDetail.length > 500) {
      alert("再開理由は500文字以内で入力してください");
      return;
    }

    try {
      // 中断記録を更新（中断終了日時を設定）
      const updatedInterrupt = await window.aivicApi.update(2, selectedInterruptRecord.中断記録ID, {
        中断終了日時: resumeTime,
        中断時間: Math.floor((new Date(resumeTime) - new Date(selectedInterruptRecord.中断開始日時)) / (1000 * 60))
      });

      // 作業記録を更新（進捗状況を「作業中」に変更）
      const updatedWork = await window.aivicApi.update(1, selectedWorkRecord.作業記録ID, {
        進捗状況: '作業中',
        備考: `${selectedWorkRecord.備考 || ''}\n[${new Date(resumeTime).toLocaleString()}] 作業再開: ${reasonCategory || reasonDetail}`.trim()
      });

      if (updatedInterrupt && updatedWork) {
        alert("作業を再開しました");
        window.showScreen("scr-1778907296658"); // 工数入力画面へ遷移
      } else {
        alert("作業再開の記録に失敗しました");
      }
    } catch (error) {
      console.error("作業再開エラー:", error);
      alert("作業再開の記録に失敗しました");
    }
  }

  // 確認ダイアログ表示
  function showConfirmDialog() {
    if (!selectedWorkRecord) {
      alert("作業が選択されていません");
      return;
    }

    const reasonDetail = container.querySelector("#resume-reason-detail").value.trim();
    const reasonCategory = container.querySelector("#resume-reason-category").value;

    if (!reasonDetail && !reasonCategory) {
      alert("再開理由を入力してください");
      return;
    }

    if (reasonDetail.length > 500) {
      alert("再開理由は500文字以内で入力してください");
      return;
    }

    const confirmDetails = container.querySelector("#confirm-work-details");
    confirmDetails.innerHTML = `
      <div><strong>作業項目:</strong> ${selectedWorkRecord.作業内容}</div>
      <div><strong>プロジェクト:</strong> ${selectedWorkRecord.プロジェクト名}</div>
      <div><strong>再開時刻:</strong> ${new Date(container.querySelector("#resume-time").value).toLocaleString()}</div>
      <div><strong>再開理由:</strong> ${reasonCategory || reasonDetail}</div>
    `;

    container.querySelector("#resume-confirm-dialog").classList.remove("hidden");
  }

  // イベントリスナー設定
  loadInitialData();

  // 戻るボタン
  container.querySelector("#btn-back").addEventListener("click", () => {
    history.back();
  });

  // 作業選択
  container.addEventListener("change", (e) => {
    if (e.target.name === "selected-work") {
      const row = e.target.closest("tr");
      const workId = row.dataset.workId;
      const interruptId = row.dataset.interruptId;
      handleWorkSelection(workId, interruptId);
    }
  });

  // 行クリックでラジオボタン選択
  container.addEventListener("click", (e) => {
    const row = e.target.closest("tr[data-work-id]");
    if (row && !e.target.matches('input[type="radio"]')) {
      const radio = row.querySelector('input[type="radio"]');
      if (radio) {
        radio.checked = true;
        radio.dispatchEvent(new Event("change"));
      }
    }
  });

  // 文字数カウント
  container.querySelector("#resume-reason-detail").addEventListener("input", updateCharCount);

  // フォームボタン
  container.querySelector("#btn-cancel-resume").addEventListener("click", () => {
    container.querySelector("#resume-form").classList.add("hidden");
    selectedWorkRecord = null;
    selectedInterruptRecord = null;
    // ラジオボタンの選択を解除
    const radios = container.querySelectorAll('input[name="selected-work"]');
    radios.forEach(radio => radio.checked = false);
  });

  container.querySelector("#btn-confirm-resume").addEventListener("click", showConfirmDialog);

  // 確認ダイアログ
  container.querySelector("#btn-dialog-cancel").addEventListener("click", () => {
    container.querySelector("#resume-confirm-dialog").classList.add("hidden");
  });

  container.querySelector("#btn-dialog-ok").addEventListener("click", () => {
    container.querySelector("#resume-confirm-dialog").classList.add("hidden");
    resumeWork();
  });

  // 初期時刻設定
  setCurrentTime();
}

function(container, apiUrl, tables) {
  // 入力チェック機能の初期化

  // チェック結果の状態管理
  let checkResults = {
    required: {
      workDate: false,
      workContent: false,
      workerId: true
    },
    format: {
      dateTime: false,
      workTime: false
    },
    anomaly: {
      longWorkTime: true,
      shortWorkTime: false
    },
    duplicate: {
      sameDateTime: true
    }
  };

  // ステータスアイコンとテキストの更新
  function updateStatus() {
    const statusIcon = container.querySelector('#status-icon');
    const statusText = container.querySelector('#status-text');
    const saveStatus = container.querySelector('#save-status');

    const hasErrors = !checkResults.required.workDate || 
                     !checkResults.required.workContent || 
                     !checkResults.format.dateTime || 
                     !checkResults.format.workTime ||
                     checkResults.anomaly.longWorkTime ||
                     checkResults.duplicate.sameDateTime;

    if (hasErrors) {
      statusIcon.style.background = '#dc3545';
      statusIcon.innerHTML = '<span style="color: #fff; font-size: 10px; font-weight: 600;">✗</span>';
      statusText.textContent = 'エラーあり - 保存不可';
      saveStatus.style.background = 'rgba(220, 53, 69, 0.1)';
      saveStatus.style.borderLeftColor = '#dc3545';
      saveStatus.innerHTML = '<span style="font-size: 12px; color: var(--text);">データ保存不可 - 入力エラーを修正してください</span>';
    } else {
      statusIcon.style.background = '#28a745';
      statusIcon.innerHTML = '<span style="color: #fff; font-size: 10px; font-weight: 600;">✓</span>';
      statusText.textContent = 'チェック通過 - 保存可能';
      saveStatus.style.background = 'rgba(40, 167, 69, 0.1)';
      saveStatus.style.borderLeftColor = '#28a745';
      saveStatus.innerHTML = '<span style="font-size: 12px; color: var(--text);">データ保存可能 - 全ての入力チェックが通過しました</span>';
    }
  }

  // 必須項目チェックの更新
  function updateRequiredChecks() {
    const requiredChecks = container.querySelector('#required-checks');
    const checks = [
      { key: 'workDate', label: '作業日', status: checkResults.required.workDate },
      { key: 'workContent', label: '作業内容', status: checkResults.required.workContent },
      { key: 'workerId', label: '作業員ID', status: checkResults.required.workerId }
    ];

    requiredChecks.innerHTML = checks.map(check => `
      <div class="check-item" style="display: flex; align-items: center; gap: 6px; margin-bottom: 4px;">
        <span class="check-icon" style="color: ${check.status ? '#28a745' : '#dc3545'};">${check.status ? '✓' : '✗'}</span>
        <span style="color: var(--text);">${check.label}: ${check.status ? '入力済み' : '未入力'}</span>
      </div>
    `).join('');
  }

  // 入力形式チェックの更新
  function updateFormatChecks() {
    const formatChecks = container.querySelector('#format-checks');
    const checks = [
      { key: 'dateTime', label: '日時形式', status: checkResults.format.dateTime, message: checkResults.format.dateTime ? '正常' : '不正な形式' },
      { key: 'workTime', label: '作業時間', status: checkResults.format.workTime, message: checkResults.format.workTime ? '正常' : '24時間超過', warning: !checkResults.format.workTime }
    ];

    formatChecks.innerHTML = checks.map(check => `
      <div class="check-item" style="display: flex; align-items: center; gap: 6px; margin-bottom: 4px;">
        <span class="check-icon" style="color: ${check.status ? '#28a745' : (check.warning ? '#ffc107' : '#dc3545')};">${check.status ? '✓' : (check.warning ? '⚠' : '✗')}</span>
        <span style="color: var(--text);">${check.label}: ${check.message}</span>
      </div>
    `).join('');
  }

  // エラー詳細確認ボタン
  container.querySelector('#btn-error-detail').addEventListener('click', () => {
    const errorDetails = container.querySelector('#error-details');
    const isVisible = errorDetails.style.display !== 'none';
    errorDetails.style.display = isVisible ? 'none' : 'block';

    if (!isVisible) {
      // エラー詳細を動的に生成
      const errors = [];
      if (!checkResults.required.workDate) {
        errors.push({ field: '作業日', message: '必須項目が未入力です', type: 'error' });
      }
      if (!checkResults.required.workContent) {
        errors.push({ field: '作業内容', message: '必須項目が未入力です', type: 'error' });
      }
      if (!checkResults.format.dateTime) {
        errors.push({ field: '開始時刻', message: '終了時刻より後の時刻が設定されています', type: 'error' });
      }
      if (!checkResults.format.workTime) {
        errors.push({ field: '作業時間', message: '24時間を超過しています（25時間）', type: 'warning' });
      }

      errorDetails.innerHTML = errors.map(error => `
        <div style="font-size: 12px; color: var(--text); margin-bottom: 6px; padding: 6px; background: rgba(${error.type === 'error' ? '220, 53, 69' : '255, 193, 7'}, 0.05); border-radius: 4px;">
          <strong>${error.field}:</strong> ${error.message}
        </div>
      `).join('');
    }
  });

  // エラーログ出力ボタン
  container.querySelector('#btn-export-log').addEventListener('click', async () => {
    try {
      // 異常値検出ログを取得
      const logs = await window.aivicApi.list(4) || []; // 異常値検出ログテーブル

      // CSVヘッダー
      const headers = ['検出日時', '異常値種別', '検出項目', '検出値', '閾値', '重要度', '確認状況'];

      // CSVデータ生成
      const csvData = logs.map(log => [
        log.検出日時 || '',
        log.異常値種別 || '',
        log.検出項目 || '',
        log.検出値 || '',
        log.閾値 || '',
        log.重要度 || '',
        log.確認状況 || ''
      ]);

      // CSV文字列作成
      const csvContent = '\uFEFF' + [headers, ...csvData]
        .map(row => row.map(field => `"${String(field).replace(/"/g, '""')}"`).join(','))
        .join('\n');

      // ダウンロード
      const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
      const link = document.createElement('a');
      link.href = URL.createObjectURL(blob);
      link.download = `error_log_${new Date().toISOString().slice(0, 10)}.csv`;
      link.click();

      // 成功通知
      const notification = document.createElement('div');
      notification.style.cssText = 'position: fixed; top: 20px; right: 20px; background: var(--primary); color: #fff; padding: 8px 12px; border-radius: 4px; font-size: 12px; z-index: 1000;';
      notification.textContent = 'エラーログを出力しました';
      document.body.appendChild(notification);
      setTimeout(() => notification.remove(), 3000);

    } catch (error) {
      console.error('エラーログ出力に失敗:', error);
      alert('エラーログの出力に失敗しました');
    }
  });

  // テスト用のチェック状態変更（実際の入力チェック処理をシミュレート）
  function simulateInputCheck(scenario) {
    switch (scenario) {
      case 'all-valid':
        checkResults = {
          required: { workDate: true, workContent: true, workerId: true },
          format: { dateTime: true, workTime: true },
          anomaly: { longWorkTime: false, shortWorkTime: false },
          duplicate: { sameDateTime: false }
        };
        break;
      case 'required-missing':
        checkResults = {
          required: { workDate: false, workContent: false, workerId: true },
          format: { dateTime: true, workTime: true },
          anomaly: { longWorkTime: false, shortWorkTime: false },
          duplicate: { sameDateTime: false }
        };
        break;
      case 'format-error':
        checkResults = {
          required: { workDate: true, workContent: true, workerId: true },
          format: { dateTime: false, workTime: false },
          anomaly: { longWorkTime: false, shortWorkTime: false },
          duplicate: { sameDateTime: false }
        };
        break;
      case 'time-conflict':
        checkResults = {
          required: { workDate: true, workContent: true, workerId: true },
          format: { dateTime: false, workTime: true },
          anomaly: { longWorkTime: false, shortWorkTime: false },
          duplicate: { sameDateTime: false }
        };
        break;
      case 'long-work-time':
        checkResults = {
          required: { workDate: true, workContent: true, workerId: true },
          format: { dateTime: true, workTime: false },
          anomaly: { longWorkTime: true, shortWorkTime: false },
          duplicate: { sameDateTime: false }
        };
        break;
      case 'duplicate-data':
        checkResults = {
          required: { workDate: true, workContent: true, workerId: true },
          format: { dateTime: true, workTime: true },
          anomaly: { longWorkTime: false, shortWorkTime: false },
          duplicate: { sameDateTime: true }
        };
        break;
      case 'short-work-time':
        checkResults = {
          required: { workDate: true, workContent: true, workerId: true },
          format: { dateTime: true, workTime: true },
          anomaly: { longWorkTime: false, shortWorkTime: true },
          duplicate: { sameDateTime: false }
        };
        break;
      case 'multiple-errors':
        checkResults = {
          required: { workDate: false, workContent: false, workerId: true },
          format: { dateTime: false, workTime: false },
          anomaly: { longWorkTime: true, shortWorkTime: false },
          duplicate: { sameDateTime: false }
        };
        break;
    }

    updateStatus();
    updateRequiredChecks();
    updateFormatChecks();
    updateValidationCount();
  }

  // 検証項目数の更新
  function updateValidationCount() {
    const validationCount = container.querySelector('#validation-count');
    const totalChecks = 8;
    const errorCount = Object.values(checkResults.required).filter(v => !v).length +
                      Object.values(checkResults.format).filter(v => !v).length +
                      Object.values(checkResults.anomaly).filter(v => v).length +
                      Object.values(checkResults.duplicate).filter(v => v).length;

    validationCount.textContent = `検証項目: ${totalChecks}件中 ${errorCount}件エラー`;
  }

  // 初期表示
  updateStatus();
  updateRequiredChecks();
  updateFormatChecks();
  updateValidationCount();

  // テスト用のグローバル関数を設定（Playwrightテスト用）
  window.simulateInputCheck = simulateInputCheck;
}

function(container, apiUrl, tables) {
  let currentError = {
    title: 'システムエラーが発生しました',
    message: '申し訳ございません。予期しないエラーが発生しました。しばらく時間をおいて再度お試しください。',
    code: 'E001',
    timestamp: new Date().toLocaleString('ja-JP', {
      year: 'numeric',
      month: '2-digit', 
      day: '2-digit',
      hour: '2-digit',
      minute: '2-digit',
      second: '2-digit'
    }).replace(/\//g, '/'),
    details: 'スタックトレース: TypeError: Cannot read property \'data\' of undefined\nファイル: /src/components/WorkRecord.js:45\nユーザーエージェント: ' + navigator.userAgent + '\nセッションID: sess_' + Math.random().toString(36).substr(2, 16),
    previousScreen: 'scr-1778907133295', // 工数記録画面
    retryAction: null
  };

  // URLパラメータからエラー情報を取得
  const urlParams = new URLSearchParams(window.location.search);
  if (urlParams.get('error')) {
    try {
      const errorData = JSON.parse(decodeURIComponent(urlParams.get('error')));
      currentError = { ...currentError, ...errorData };
    } catch (e) {
      console.warn('エラーパラメータの解析に失敗:', e);
    }
  }

  // エラー情報を画面に反映
  function displayError() {
    container.querySelector('#error-title').textContent = currentError.title;
    container.querySelector('#error-message').textContent = currentError.message;
    container.querySelector('#error-code').textContent = `エラーコード: ${currentError.code}`;
    container.querySelector('#error-timestamp').textContent = `発生時刻: ${currentError.timestamp}`;
    container.querySelector('#error-details-content').innerHTML = currentError.details.split('\n').map(line => `<div>${line}</div>`).join('');
  }

  displayError();

  // 再試行ボタン
  let isRetrying = false;
  container.querySelector('#btn-retry').addEventListener('click', async () => {
    if (isRetrying) return;

    const retryBtn = container.querySelector('#btn-retry');
    isRetrying = true;
    retryBtn.textContent = '再試行中...';
    retryBtn.style.opacity = '0.6';

    try {
      // ネットワーク接続チェック
      if (!navigator.onLine) {
        throw new Error('ネットワーク接続がありません');
      }

      // セッション確認
      const sessionCheck = await fetch('/api/session/check').catch(() => null);
      if (!sessionCheck || !sessionCheck.ok) {
        // セッション切れの場合はログイン画面へ
        window.location.href = './login.html';
        return;
      }

      // 元の画面に戻る
      if (currentError.previousScreen) {
        window.showScreen(currentError.previousScreen);
      } else {
        window.showScreen('scr-1778907133295'); // デフォルトで工数記録画面
      }
    } catch (error) {
      // 再試行失敗
      currentError.message = '再試行に失敗しました。ネットワーク接続を確認してください。';
      currentError.timestamp = new Date().toLocaleString('ja-JP', {
        year: 'numeric',
        month: '2-digit', 
        day: '2-digit',
        hour: '2-digit',
        minute: '2-digit',
        second: '2-digit'
      }).replace(/\//g, '/');
      displayError();
    } finally {
      isRetrying = false;
      retryBtn.textContent = '再試行';
      retryBtn.style.opacity = '1';
    }
  });

  // 戻るボタン
  container.querySelector('#btn-back').addEventListener('click', () => {
    // セッション確認
    fetch('/api/session/check').then(response => {
      if (!response.ok) {
        window.location.href = './login.html';
        return;
      }

      if (currentError.previousScreen) {
        window.showScreen(currentError.previousScreen);
      } else {
        window.history.back();
      }
    }).catch(() => {
      window.location.href = './login.html';
    });
  });

  // ホームに戻るボタン
  container.querySelector('#btn-home').addEventListener('click', () => {
    window.showScreen('scr-1778907133295'); // 工数記録画面（ホーム）
  });

  // 管理者に連絡ボタン
  container.querySelector('#btn-contact-admin').addEventListener('click', async () => {
    try {
      // 管理者連絡機能の確認
      const response = await fetch('/api/admin/contact/check').catch(() => null);

      if (!response || !response.ok) {
        // 連絡機能が利用できない場合は代替連絡方法を表示
        container.querySelector('#contact-fallback').classList.remove('hidden');
        return;
      }

      // 緊急報告画面に遷移
      window.showScreen('scr-1778907330826');
    } catch (error) {
      container.querySelector('#contact-fallback').classList.remove('hidden');
    }
  });

  // エラー詳細表示ボタン
  container.querySelector('#btn-show-details').addEventListener('click', async () => {
    const detailsDiv = container.querySelector('#error-details');
    const btn = container.querySelector('#btn-show-details');

    if (detailsDiv.classList.contains('hidden')) {
      try {
        // 詳細情報の取得を試行
        const response = await fetch(`/api/errors/${currentError.code}/details`).catch(() => null);

        if (response && response.ok) {
          const detailData = await response.json();
          container.querySelector('#error-details-content').innerHTML = 
            detailData.details.split('\n').map(line => `<div>${line}</div>`).join('');
        } else {
          // 詳細情報が取得できない場合
          container.querySelector('#error-details-content').innerHTML = 
            '<div>エラーの詳細情報を取得できませんでした。</div><div>一般的なエラーが発生している可能性があります。</div>';
        }

        detailsDiv.classList.remove('hidden');
        btn.textContent = 'エラー詳細を隠す';
      } catch (error) {
        container.querySelector('#error-details-content').innerHTML = 
          '<div>エラーの詳細情報を取得できませんでした。</div><div>ネットワーク接続を確認してください。</div>';
        detailsDiv.classList.remove('hidden');
        btn.textContent = 'エラー詳細を隠す';
      }
    } else {
      detailsDiv.classList.add('hidden');
      btn.textContent = 'エラー詳細表示';
    }
  });

  // 長いエラーメッセージの制限
  const messageElement = container.querySelector('#error-message');
  if (currentError.message && currentError.message.length > 500) {
    messageElement.textContent = currentError.message.substring(0, 500) + '...';
    messageElement.title = currentError.message; // ホバーで全文表示
  }

  // ネットワーク状態の監視
  window.addEventListener('online', () => {
    const retryBtn = container.querySelector('#btn-retry');
    if (retryBtn.textContent === '再試行') {
      retryBtn.style.background = 'var(--primary)';
      retryBtn.style.opacity = '1';
    }
  });

  window.addEventListener('offline', () => {
    const retryBtn = container.querySelector('#btn-retry');
    retryBtn.style.background = 'var(--text-muted)';
    retryBtn.style.opacity = '0.6';
  });
}

function(container, apiUrl, tables) {
  let interruptions = [];

  // 作業項目マスタのデータを取得してドロップダウンに設定
  function loadWorkItems() {
    const workItemSelect = container.querySelector("#work-item");
    const workItemsTable = tables.find(t => t.tableName === "作業項目マスタ");
    if (workItemsTable && workItemsTable.records) {
      workItemsTable.records.forEach(item => {
        const option = document.createElement("option");
        option.value = item.作業項目ID;
        option.textContent = `${item.作業項目コード} - ${item.作業項目名}`;
        workItemSelect.appendChild(option);
      });
    }
  }

  // 実働時間を計算
  function calculateActualTime() {
    const startTime = container.querySelector("#start-time").value;
    const endTime = container.querySelector("#end-time").value;
    const breakTime = parseInt(container.querySelector("#break-time").value) || 0;

    if (!startTime || !endTime) {
      container.querySelector("#actual-time").value = "";
      return;
    }

    const start = new Date(`2000-01-01 ${startTime}`);
    let end = new Date(`2000-01-01 ${endTime}`);

    // 24時間をまたぐ場合の処理
    if (end <= start) {
      end.setDate(end.getDate() + 1);
    }

    const diffMs = end - start;
    const totalMinutes = Math.floor(diffMs / (1000 * 60));
    const actualMinutes = totalMinutes - breakTime;

    if (actualMinutes < 0) {
      container.querySelector("#actual-time").value = "";
      return;
    }

    const hours = Math.floor(actualMinutes / 60);
    const minutes = actualMinutes % 60;
    container.querySelector("#actual-time").value = `${hours}時間${minutes.toString().padStart(2, '0')}分`;
  }

  // エラーメッセージ表示
  function showError(message) {
    const errorDiv = container.querySelector("#error-message");
    const successDiv = container.querySelector("#success-message");
    errorDiv.textContent = message;
    errorDiv.style.display = "block";
    successDiv.style.display = "none";
  }

  // 成功メッセージ表示
  function showSuccess(message) {
    const errorDiv = container.querySelector("#error-message");
    const successDiv = container.querySelector("#success-message");
    successDiv.textContent = message;
    successDiv.style.display = "block";
    errorDiv.style.display = "none";
  }

  // メッセージを隠す
  function hideMessages() {
    container.querySelector("#error-message").style.display = "none";
    container.querySelector("#success-message").style.display = "none";
  }

  // バリデーション
  function validateForm() {
    const workDate = container.querySelector("#work-date").value;
    const startTime = container.querySelector("#start-time").value;
    const endTime = container.querySelector("#end-time").value;
    const breakTime = parseInt(container.querySelector("#break-time").value) || 0;
    const workItem = container.querySelector("#work-item").value;
    const workLocation = container.querySelector("#work-location").value;
    const workerName = container.querySelector("#worker-name").value;
    const workDetails = container.querySelector("#work-details").value;

    // 必須項目チェック
    if (!workDate || !startTime || !workItem || !workLocation || !workerName || !workDetails) {
      showError("必須項目をすべて入力してください。");
      return false;
    }

    // 未来日付チェック
    const today = new Date();
    const selectedDate = new Date(workDate);
    today.setHours(0, 0, 0, 0);
    selectedDate.setHours(0, 0, 0, 0);
    if (selectedDate > today) {
      showError("未来の日付は選択できません。");
      return false;
    }

    // 時刻フォーマットチェック
    const timeRegex = /^([01]?[0-9]|2[0-3]):[0-5][0-9]$/;
    if (!timeRegex.test(startTime)) {
      showError("開始時刻の形式が正しくありません。");
      return false;
    }
    if (endTime && !timeRegex.test(endTime)) {
      showError("終了時刻の形式が正しくありません。");
      return false;
    }

    if (endTime) {
      // 開始時刻と終了時刻が同じ場合
      if (startTime === endTime) {
        showError("開始時刻と終了時刻が同じです。");
        return false;
      }

      // 実働時間計算
      const start = new Date(`2000-01-01 ${startTime}`);
      let end = new Date(`2000-01-01 ${endTime}`);

      if (end <= start) {
        end.setDate(end.getDate() + 1);
      }

      const diffMs = end - start;
      const totalMinutes = Math.floor(diffMs / (1000 * 60));

      // 休憩時間が実働時間を超過チェック
      if (breakTime >= totalMinutes) {
        showError("休憩時間が実働時間を超過しています。");
        return false;
      }
    }

    // 文字数制限チェック
    if (workDetails.length > 1000) {
      showError("作業内容詳細は1000文字以内で入力してください。");
      return false;
    }

    return true;
  }

  // 中断記録を表示
  function renderInterruptions() {
    const listDiv = container.querySelector("#interruption-list");
    if (interruptions.length === 0) {
      listDiv.innerHTML = "";
      return;
    }

    listDiv.innerHTML = interruptions.map((item, index) => `
      <div style="display: flex; align-items: center; justify-content: space-between; padding: 8px 12px; background: rgba(255,255,255,0.02); border-radius: 6px; margin-bottom: 8px;">
        <span style="color: var(--text); font-size: 13px;">
          ${item.reason} (${item.startTime} - ${item.endTime || "進行中"})
        </span>
        <button class="action-btn secondary remove-interruption" data-index="${index}" style="font-size: 11px; padding: 4px 8px;">削除</button>
      </div>
    `).join("");
  }

  // 初期化
  loadWorkItems();

  // 今日の日付を設定
  const today = new Date();
  container.querySelector("#work-date").value = today.toISOString().split('T')[0];

  // 文字数カウント
  container.querySelector("#work-details").addEventListener("input", function() {
    const count = this.value.length;
    container.querySelector("#char-count").textContent = count;
  });

  // 時刻変更時の実働時間計算
  container.querySelector("#start-time").addEventListener("change", calculateActualTime);
  container.querySelector("#end-time").addEventListener("change", calculateActualTime);
  container.querySelector("#break-time").addEventListener("input", calculateActualTime);

  // 進捗状況変更時の中断セクション表示制御
  container.querySelector("#progress-status").addEventListener("change", function() {
    const interruptionSection = container.querySelector("#interruption-section");
    if (this.value === "中断") {
      interruptionSection.style.display = "block";
    } else {
      interruptionSection.style.display = "none";
    }
  });

  // 中断記録追加
  container.querySelector("#btn-add-interruption").addEventListener("click", function() {
    const reason = container.querySelector("#interruption-reason").value;
    const startTime = container.querySelector("#interruption-start").value;
    const endTime = container.querySelector("#interruption-end").value;

    if (!reason || !startTime) {
      showError("中断理由と開始時刻を入力してください。");
      return;
    }

    interruptions.push({
      reason: reason,
      startTime: startTime,
      endTime: endTime
    });

    renderInterruptions();

    // フィールドをクリア
    container.querySelector("#interruption-reason").value = "";
    container.querySelector("#interruption-start").value = "";
    container.querySelector("#interruption-end").value = "";

    hideMessages();
  });

  // 中断記録削除
  container.addEventListener("click", function(e) {
    const removeBtn = e.target.closest(".remove-interruption");
    if (removeBtn) {
      const index = parseInt(removeBtn.dataset.index);
      interruptions.splice(index, 1);
      renderInterruptions();
    }
  });

  // クリアボタン
  container.querySelector("#btn-clear").addEventListener("click", function() {
    container.querySelector("#work-form").reset();
    container.querySelector("#work-details").value = "";
    container.querySelector("#char-count").textContent = "0";
    container.querySelector("#actual-time").value = "";
    interruptions = [];
    renderInterruptions();
    container.querySelector("#interruption-section").style.display = "none";
    hideMessages();

    // 今日の日付を再設定
    const today = new Date();
    container.querySelector("#work-date").value = today.toISOString().split('T')[0];
  });

  // 登録ボタン
  container.querySelector("#btn-save").addEventListener("click", async function() {
    if (!validateForm()) return;

    const workData = {
      作業員ID: "current-user-id", // 実際の実装では認証済みユーザーIDを使用
      作業日: container.querySelector("#work-date").value,
      作業開始時刻: `${container.querySelector("#work-date").value} ${container.querySelector("#start-time").value}`,
      作業終了時刻: container.querySelector("#end-time").value ? `${container.querySelector("#work-date").value} ${container.querySelector("#end-time").value}` : null,
      プロジェクト名: container.querySelector("#work-item").selectedOptions[0]?.textContent || "",
      作業場所: container.querySelector("#work-location").value,
      作業種別: container.querySelector("#work-item").selectedOptions[0]?.textContent.split(" - ")[1] || "",
      作業内容: container.querySelector("#work-details").value,
      進捗状況: container.querySelector("#progress-status").value,
      承認状態: "未承認",
      作成者ID: "current-user-id"
    };

    // 作業時間を計算
    if (workData.作業終了時刻) {
      const start = new Date(workData.作業開始時刻);
      const end = new Date(workData.作業終了時刻);
      const breakTime = parseInt(container.querySelector("#break-time").value) || 0;

      if (end <= start) {
        end.setDate(end.getDate() + 1);
      }

      const diffMs = end - start;
      const totalMinutes = Math.floor(diffMs / (1000 * 60));
      workData.作業時間 = totalMinutes - breakTime;
    }

    try {
      const saved = await window.aivicApi.save(1, workData); // 作業記録テーブルのインデックス
      if (saved) {
        // 中断記録も保存
        for (const interruption of interruptions) {
          const interruptionData = {
            作業記録ID: saved.作業記録ID,
            中断開始日時: `${container.querySelector("#work-date").value} ${interruption.startTime}`,
            中断終了日時: interruption.endTime ? `${container.querySelector("#work-date").value} ${interruption.endTime}` : null,
            中断理由区分: interruption.reason,
            対応状況: "対応中",
            記録者ID: "current-user-id"
          };

          if (interruptionData.中断終了日時) {
            const start = new Date(interruptionData.中断開始日時);
            const end = new Date(interruptionData.中断終了日時);
            const diffMs = end - start;
            interruptionData.中断時間 = Math.floor(diffMs / (1000 * 60));
          }

          await window.aivicApi.save(2, interruptionData); // 中断記録テーブルのインデックス
        }

        showSuccess("工数記録が正常に登録されました。");

        // フォームをクリア
        setTimeout(() => {
          container.querySelector("#btn-clear").click();
        }, 2000);
      }
    } catch (error) {
      showError("登録に失敗しました。もう一度お試しください。");
    }
  });

  // 作業中断ボタン
  container.querySelector("#btn-interrupt").addEventListener("click", function() {
    window.showScreen("scr-1778907238439");
  });

  // 作業終了ボタン
  container.querySelector("#btn-finish").addEventListener("click", function() {
    window.showScreen("scr-1778907199709");
  });
}

function(container, apiUrl, tables) {
  let workRecords = [];
  let breakRecords = [];
  let workItems = [];
  let selectedRecord = null;

  // 初期データ読み込み
  async function loadInitialData() {
    try {
      workRecords = await window.aivicApi.list(1) || tables[1]?.records || [];
      breakRecords = await window.aivicApi.list(2) || tables[2]?.records || [];
      workItems = await window.aivicApi.list(3) || tables[3]?.records || [];

      renderTargetRecords();
      renderWorkItems();
    } catch (error) {
      console.error('データ読み込みエラー:', error);
    }
  }

  // 修正対象記録の描画
  function renderTargetRecords() {
    const select = container.querySelector('#select-target-record');
    select.innerHTML = '<option value="">選択してください</option>';

    workRecords.forEach(record => {
      const option = document.createElement('option');
      option.value = record.作業記録ID || record.id;
      option.textContent = `${record.作業日 || ''} - ${record.作業内容 || record.プロジェクト名 || ''}`;
      select.appendChild(option);
    });
  }

  // 作業項目の描画
  function renderWorkItems() {
    const select = container.querySelector('#select-work-item');
    select.innerHTML = '<option value="">選択してください</option>';

    workItems.filter(item => item.有効フラグ !== false).forEach(item => {
      const option = document.createElement('option');
      option.value = item.作業項目ID || item.id;
      option.textContent = item.作業項目名 || item.name;
      select.appendChild(option);
    });
  }

  // 修正前データ表示
  function displayOriginalData(record) {
    const display = container.querySelector('#original-data-display');
    if (!record) {
      display.innerHTML = '修正対象記録を選択してください';
      return;
    }

    const breakRecord = breakRecords.find(br => br.作業記録ID === record.作業記録ID || br.作業記録ID === record.id);

    display.innerHTML = `
      <div style="display: grid; grid-template-columns: 1fr 1fr; gap: 12px;">
        <div>作業日: ${record.作業日 || ''}</div>
        <div>作業項目: ${record.作業種別 || record.プロジェクト名 || ''}</div>
        <div>開始時刻: ${formatTime(record.作業開始時刻) || ''}</div>
        <div>終了時刻: ${formatTime(record.作業終了時刻) || ''}</div>
        <div>中断時刻: ${breakRecord ? formatTime(breakRecord.中断開始日時) : 'なし'}</div>
        <div>中断理由: ${breakRecord ? breakRecord.中断理由区分 : 'なし'}</div>
      </div>
    `;
  }

  // 時刻フォーマット
  function formatTime(dateTime) {
    if (!dateTime) return '';
    const date = new Date(dateTime);
    return date.toTimeString().substring(0, 5);
  }

  // 時間計算
  function calculateTimes() {
    const startTime = container.querySelector('#input-start-time').value;
    const endTime = container.querySelector('#input-end-time').value;
    const breakTime = container.querySelector('#input-break-time').value;

    if (startTime && endTime) {
      const start = new Date(`2000-01-01T${startTime}`);
      const end = new Date(`2000-01-01T${endTime}`);

      if (end > start) {
        const totalMinutes = (end - start) / (1000 * 60);
        let actualMinutes = totalMinutes;

        if (breakTime && startTime <= breakTime && breakTime <= endTime) {
          const breakDuration = 60; // 仮の中断時間（分）
          actualMinutes = totalMinutes - breakDuration;
          container.querySelector('#break-duration-display').textContent = `${breakDuration}分`;
        } else {
          container.querySelector('#break-duration-display').textContent = '0分';
        }

        const hours = Math.floor(actualMinutes / 60);
        const minutes = actualMinutes % 60;
        container.querySelector('#actual-work-time-display').textContent = `${hours}時間${minutes}分`;
      }
    }
  }

  // バリデーション
  function validateInput() {
    const errors = [];
    const warnings = [];

    const targetRecord = container.querySelector('#select-target-record').value;
    const correctionReason = container.querySelector('#input-correction-reason').value.trim();
    const workDate = container.querySelector('#input-work-date').value;
    const startTime = container.querySelector('#input-start-time').value;
    const endTime = container.querySelector('#input-end-time').value;
    const breakTime = container.querySelector('#input-break-time').value;

    if (!targetRecord) {
      errors.push('修正対象の記録が選択されていません');
    }

    if (!correctionReason) {
      errors.push('修正理由を入力してください');
    }

    if (workDate) {
      const date = new Date(workDate);
      const today = new Date();
      if (date > today) {
        errors.push('作業日付に未来の日付は入力できません');
      }
      if (date.getFullYear() < 1900 || date.getFullYear() > 2099) {
        errors.push('作業日付は1900年から2099年の範囲で入力してください');
      }
    }

    if (startTime && endTime) {
      if (startTime >= endTime) {
        errors.push('開始時刻は終了時刻より前の時刻を入力してください');
      }

      const start = new Date(`2000-01-01T${startTime}`);
      const end = new Date(`2000-01-01T${endTime}`);
      const workHours = (end - start) / (1000 * 60 * 60);

      if (workHours > 20) {
        warnings.push('20時間を超える長時間作業が検出されました');
      }
    }

    if (breakTime && startTime && endTime) {
      if (breakTime < startTime || breakTime > endTime) {
        errors.push('中断時刻が作業時間外です');
      }
    }

    return { errors, warnings };
  }

  // エラー・警告表示
  function showValidationResults(errors, warnings) {
    const errorArea = container.querySelector('#error-area');
    const warningArea = container.querySelector('#warning-area');

    if (errors.length > 0) {
      container.querySelector('#error-message').textContent = errors.join(', ');
      errorArea.style.display = 'block';
    } else {
      errorArea.style.display = 'none';
    }

    if (warnings.length > 0) {
      container.querySelector('#warning-messages').innerHTML = warnings.map(w => `<div>• ${w}</div>`).join('');
      warningArea.style.display = 'block';
    } else {
      warningArea.style.display = 'none';
    }
  }

  // 文字数カウント
  function updateCharCount() {
    const textarea = container.querySelector('#input-correction-reason');
    const counter = container.querySelector('#reason-char-count');
    counter.textContent = textarea.value.length;
  }

  // イベントリスナー
  container.querySelector('#select-target-record').addEventListener('change', function() {
    const recordId = this.value;
    selectedRecord = workRecords.find(r => (r.作業記録ID || r.id) === recordId);

    if (selectedRecord) {
      displayOriginalData(selectedRecord);

      // フォームに既存データを設定
      container.querySelector('#input-work-date').value = selectedRecord.作業日 ? selectedRecord.作業日.split('T')[0] : '';
      container.querySelector('#input-start-time').value = formatTime(selectedRecord.作業開始時刻);
      container.querySelector('#input-end-time').value = formatTime(selectedRecord.作業終了時刻);

      const breakRecord = breakRecords.find(br => br.作業記録ID === recordId);
      if (breakRecord) {
        container.querySelector('#input-break-time').value = formatTime(breakRecord.中断開始日時);
        container.querySelector('#select-break-reason').value = breakRecord.中断理由区分 || '';
      }
    } else {
      displayOriginalData(null);
    }
  });

  container.querySelector('#input-correction-reason').addEventListener('input', updateCharCount);

  ['#input-start-time', '#input-end-time', '#input-break-time'].forEach(selector => {
    container.querySelector(selector).addEventListener('change', calculateTimes);
  });

  container.querySelector('#btn-save').addEventListener('click', async function() {
    const validation = validateInput();
    showValidationResults(validation.errors, validation.warnings);

    if (validation.errors.length > 0) {
      return;
    }

    try {
      const updateData = {
        作業日: container.querySelector('#input-work-date').value,
        作業開始時刻: container.querySelector('#input-work-date').value + 'T' + container.querySelector('#input-start-time').value,
        作業終了時刻: container.querySelector('#input-work-date').value + 'T' + container.querySelector('#input-end-time').value,
        作業種別: container.querySelector('#select-work-item').value,
        更新日時: new Date().toISOString()
      };

      await window.aivicApi.update(1, selectedRecord.作業記録ID || selectedRecord.id, updateData);

      // 中断記録の更新
      const breakTime = container.querySelector('#input-break-time').value;
      const breakReason = container.querySelector('#select-break-reason').value;

      if (breakTime && breakReason) {
        const existingBreak = breakRecords.find(br => br.作業記録ID === (selectedRecord.作業記録ID || selectedRecord.id));
        const breakData = {
          作業記録ID: selectedRecord.作業記録ID || selectedRecord.id,
          中断開始日時: container.querySelector('#input-work-date').value + 'T' + breakTime,
          中断理由区分: breakReason,
          更新日時: new Date().toISOString()
        };

        if (existingBreak) {
          await window.aivicApi.update(2, existingBreak.中断記録ID || existingBreak.id, breakData);
        } else {
          await window.aivicApi.save(2, {
            ...breakData,
            中断記録ID: crypto.randomUUID(),
            記録者ID: selectedRecord.作業員ID,
            対応状況: '未対応',
            作成日時: new Date().toISOString()
          });
        }
      }

      alert('修正が正常に保存されました');
      window.showScreen('scr-1778907145716'); // 作業履歴一覧画面
    } catch (error) {
      console.error('保存エラー:', error);
      showValidationResults(['保存に失敗しました'], []);
    }
  });

  container.querySelector('#btn-cancel').addEventListener('click', function() {
    window.showScreen('scr-1778907145716'); // 作業履歴一覧画面
  });

  // 初期化
  loadInitialData();
}

function(container, apiUrl, tables) {
  let selectedUrgency = '';
  let uploadedPhotos = [];
  const maxPhotos = 5;
  const maxFileSize = 5 * 1024 * 1024; // 5MB
  const maxContentLength = 1000;

  // 現在のユーザー情報を設定（仮データ）
  const currentUser = { name: '田中太郎', id: 'user001' };
  container.querySelector('#reporter-name').value = currentUser.name;

  // 作業項目マスタを読み込み
  async function loadWorkItems() {
    const workItemsTable = tables.find(t => t.tableName === '作業項目マスタ');
    if (workItemsTable) {
      const workItemSelect = container.querySelector('#work-item');
      workItemsTable.records.forEach(item => {
        const option = document.createElement('option');
        option.value = item.作業項目ID;
        option.textContent = `${item.作業項目コード} - ${item.作業項目名}`;
        workItemSelect.appendChild(option);
      });
    }
  }

  // 緊急度ボタンの処理
  function setupUrgencyButtons() {
    const urgencyButtons = container.querySelectorAll('.urgency-btn');
    urgencyButtons.forEach(btn => {
      btn.addEventListener('click', () => {
        urgencyButtons.forEach(b => {
          b.style.background = 'transparent';
          b.style.color = 'var(--text)';
        });
        btn.style.background = 'var(--primary)';
        btn.style.color = '#fff';
        selectedUrgency = btn.dataset.value;
      });
    });
  }

  // 文字数カウンター
  function setupContentCounter() {
    const textarea = container.querySelector('#emergency-content');
    const counter = container.querySelector('#content-counter');

    textarea.addEventListener('input', () => {
      const length = textarea.value.length;
      counter.textContent = length;
      if (length > maxContentLength) {
        counter.style.color = '#fca5a5';
        textarea.style.borderColor = 'rgba(220, 38, 38, 0.5)';
      } else {
        counter.style.color = 'var(--text-muted)';
        textarea.style.borderColor = 'rgba(255,255,255,0.18)';
      }
    });
  }

  // 写真アップロード処理
  function setupPhotoUpload() {
    const uploadArea = container.querySelector('#photo-upload-area');
    const photoInput = container.querySelector('#photo-input');
    const photoPreview = container.querySelector('#photo-preview');

    uploadArea.addEventListener('click', () => photoInput.click());

    uploadArea.addEventListener('dragover', (e) => {
      e.preventDefault();
      uploadArea.style.borderColor = 'var(--primary)';
      uploadArea.style.background = 'rgba(0,0,0,0.2)';
    });

    uploadArea.addEventListener('dragleave', () => {
      uploadArea.style.borderColor = 'rgba(255,255,255,0.18)';
      uploadArea.style.background = 'rgba(0,0,0,0.1)';
    });

    uploadArea.addEventListener('drop', (e) => {
      e.preventDefault();
      uploadArea.style.borderColor = 'rgba(255,255,255,0.18)';
      uploadArea.style.background = 'rgba(0,0,0,0.1)';
      handleFiles(e.dataTransfer.files);
    });

    photoInput.addEventListener('change', (e) => {
      handleFiles(e.target.files);
    });

    function handleFiles(files) {
      Array.from(files).forEach(file => {
        if (uploadedPhotos.length >= maxPhotos) {
          showError(['写真は最大5枚までアップロードできます。']);
          return;
        }

        if (!file.type.startsWith('image/')) {
          showError(['サポートされていないファイル形式です。JPG、PNG形式のファイルをアップロードしてください。']);
          return;
        }

        if (file.size > maxFileSize) {
          showError(['ファイルサイズが上限を超えています。5MB以下のファイルをアップロードしてください。']);
          return;
        }

        const reader = new FileReader();
        reader.onload = (e) => {
          const photoData = {
            id: Date.now() + Math.random(),
            file: file,
            dataUrl: e.target.result
          };
          uploadedPhotos.push(photoData);
          renderPhotoPreview();
        };
        reader.readAsDataURL(file);
      });
    }

    function renderPhotoPreview() {
      photoPreview.innerHTML = uploadedPhotos.map(photo => `
        <div style="position: relative; border-radius: 6px; overflow: hidden; background: rgba(0,0,0,0.2);">
          <img src="${photo.dataUrl}" style="width: 100%; height: 80px; object-fit: cover;">
          <button class="remove-photo-btn" data-id="${photo.id}" style="position: absolute; top: 4px; right: 4px; width: 20px; height: 20px; border: none; border-radius: 50%; background: rgba(220, 38, 38, 0.8); color: #fff; font-size: 12px; cursor: pointer; display: flex; align-items: center; justify-content: center;">×</button>
        </div>
      `).join('');
    }

    photoPreview.addEventListener('click', (e) => {
      const removeBtn = e.target.closest('.remove-photo-btn');
      if (removeBtn) {
        const photoId = parseFloat(removeBtn.dataset.id);
        uploadedPhotos = uploadedPhotos.filter(p => p.id !== photoId);
        renderPhotoPreview();
      }
    });
  }

  // バリデーション
  function validateForm() {
    const errors = [];

    if (!selectedUrgency) {
      errors.push('緊急度を選択してください。');
    }

    if (!container.querySelector('#report-type').value) {
      errors.push('報告種別を選択してください。');
    }

    if (!container.querySelector('#occurrence-datetime').value) {
      errors.push('発生日時を入力してください。');
    } else {
      const occurrenceDate = new Date(container.querySelector('#occurrence-datetime').value);
      const now = new Date();
      if (occurrenceDate > now) {
        errors.push('発生日時に未来の日付は入力できません。');
      }
    }

    if (!container.querySelector('#occurrence-location').value.trim()) {
      errors.push('発生場所を入力してください。');
    }

    const content = container.querySelector('#emergency-content').value.trim();
    if (!content) {
      errors.push('緊急事態内容を入力してください。');
    } else if (content.length > maxContentLength) {
      errors.push('緊急事態内容は1000文字以内で入力してください。');
    }

    if (!container.querySelector('#contact-phone').value.trim()) {
      errors.push('連絡先電話番号を入力してください。');
    } else {
      const phone = container.querySelector('#contact-phone').value.trim();
      const phonePattern = /^(\d{2,4}-\d{2,4}-\d{4}|\d{10,11})$/;
      if (!phonePattern.test(phone)) {
        errors.push('正しい電話番号の形式で入力してください。');
      }
    }

    return errors;
  }

  // エラー表示
  function showError(errors) {
    const errorDiv = container.querySelector('#error-messages');
    const errorList = container.querySelector('#error-list');

    if (errors.length > 0) {
      errorList.innerHTML = errors.map(error => `• ${error}`).join('<br>');
      errorDiv.classList.remove('hidden');
      errorDiv.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
    } else {
      errorDiv.classList.add('hidden');
    }
  }

  // 成功メッセージ表示
  function showSuccess() {
    container.querySelector('#success-message').classList.remove('hidden');
    container.querySelector('#success-message').scrollIntoView({ behavior: 'smooth' });
  }

  // フォームリセット
  function resetForm() {
    selectedUrgency = '';
    uploadedPhotos = [];
    container.querySelectorAll('.urgency-btn').forEach(btn => {
      btn.style.background = 'transparent';
      btn.style.color = 'var(--text)';
    });
    container.querySelector('#report-type').value = '';
    container.querySelector('#occurrence-datetime').value = '';
    container.querySelector('#occurrence-location').value = '';
    container.querySelector('#work-item').value = '';
    container.querySelector('#emergency-content').value = '';
    container.querySelector('#contact-phone').value = '';
    container.querySelector('#content-counter').textContent = '0';
    container.querySelector('#photo-preview').innerHTML = '';
    showError([]);
  }

  // 緊急報告送信
  async function submitReport(isDraft = false) {
    if (!isDraft) {
      const errors = validateForm();
      if (errors.length > 0) {
        showError(errors);
        return;
      }
    }

    const reportData = {
      緊急度: selectedUrgency,
      報告種別: container.querySelector('#report-type').value,
      発生日時: container.querySelector('#occurrence-datetime').value,
      発生場所: container.querySelector('#occurrence-location').value,
      作業項目ID: container.querySelector('#work-item').value,
      緊急事態内容: container.querySelector('#emergency-content').value,
      報告者名: container.querySelector('#reporter-name').value,
      連絡先電話番号: container.querySelector('#contact-phone').value,
      添付写真数: uploadedPhotos.length,
      下書きフラグ: isDraft,
      報告日時: new Date().toISOString(),
      報告者ID: currentUser.id
    };

    // 緊急報告テーブルに保存（テーブルインデックス0と仮定）
    const saved = await window.aivicApi.save(0, reportData);

    if (saved) {
      if (isDraft) {
        alert('下書きが保存されました。');
      } else {
        showSuccess();
        resetForm();
      }
    }
  }

  // イベントリスナー設定
  container.querySelector('#btn-submit').addEventListener('click', () => submitReport(false));
  container.querySelector('#btn-draft-save').addEventListener('click', () => submitReport(true));

  container.querySelector('#btn-back-to-work').addEventListener('click', () => {
    window.showScreen("scr-1778907133295");
  });

  // 初期化
  loadWorkItems();
  setupUrgencyButtons();
  setupContentCounter();
  setupPhotoUpload();
}

function(container, apiUrl, tables) {
  let currentRecord = null;
  let originalRecord = null;
  let workItems = [];

  // 作業項目マスタを読み込み
  async function loadWorkItems() {
    const items = await window.aivicApi.list(3); // 作業項目マスタ
    if (items) {
      workItems = items.filter(item => item.有効フラグ);
      const select = container.querySelector("#select-work-item");
      select.innerHTML = '<option value="">選択してください</option>';
      workItems.forEach(item => {
        select.innerHTML += `<option value="${item.作業項目ID}">${item.作業項目名}</option>`;
      });
    }
  }

  // 作業記録一覧を読み込み
  async function loadWorkRecords() {
    const records = await window.aivicApi.list(1); // 作業記録
    if (records) {
      const select = container.querySelector("#select-work-record");
      select.innerHTML = '<option value="">選択してください</option>';
      records.forEach(record => {
        const date = new Date(record.作業日).toLocaleDateString('ja-JP');
        const content = record.作業内容 ? record.作業内容.substring(0, 20) + '...' : '';
        select.innerHTML += `<option value="${record.作業記録ID}">${date} - ${content}</option>`;
      });
    }
  }

  // 時刻計算
  function calculateDuration() {
    const startTime = container.querySelector("#input-start-time").value;
    const endTime = container.querySelector("#input-end-time").value;
    const breakTime = parseInt(container.querySelector("#input-break-time").value) || 0;

    if (startTime && endTime) {
      const start = new Date(`2000-01-01 ${startTime}`);
      let end = new Date(`2000-01-01 ${endTime}`);

      // 24時間跨ぎの場合
      if (end < start) {
        end.setDate(end.getDate() + 1);
      }

      const diffMs = end - start;
      const totalMinutes = Math.floor(diffMs / (1000 * 60));
      const netMinutes = totalMinutes - breakTime;

      const hours = Math.floor(totalMinutes / 60);
      const minutes = totalMinutes % 60;
      container.querySelector("#display-work-duration").value = `${hours}時間${minutes}分`;

      const netHours = Math.floor(netMinutes / 60);
      const netMins = netMinutes % 60;
      container.querySelector("#display-net-work-time").value = `${netHours}時間${netMins}分`;

      // バリデーション
      validateTimes(start, end, totalMinutes, breakTime);
    }
  }

  // バリデーション
  function validateTimes(start, end, totalMinutes, breakTime) {
    const warningArea = container.querySelector("#warning-area");
    const errorArea = container.querySelector("#error-area");

    warningArea.style.display = "none";
    errorArea.style.display = "none";

    // 開始時刻が終了時刻より後
    if (start >= end && end.getDate() === start.getDate()) {
      showError("作業開始時刻は終了時刻より前の時刻を入力してください");
      return false;
    }

    // 作業時間が0分
    if (totalMinutes === 0) {
      showError("作業時間が0分です。開始時刻と終了時刻を確認してください。");
      return false;
    }

    // 中断時間が作業時間を超過
    if (breakTime > totalMinutes) {
      showError("中断時間が作業時間を超過しています");
      return false;
    }

    // 異常な作業時間の警告（12時間以上）
    if (totalMinutes > 720) {
      showWarning("作業時間が12時間を超えています。確認してください。");
    }

    return true;
  }

  function showError(message) {
    const errorArea = container.querySelector("#error-area");
    errorArea.textContent = message;
    errorArea.style.display = "block";
  }

  function showWarning(message) {
    const warningArea = container.querySelector("#warning-area");
    warningArea.textContent = message;
    warningArea.style.display = "block";
  }

  // 作業記録選択時の処理
  container.querySelector("#select-work-record").addEventListener("change", async function() {
    const recordId = this.value;
    if (!recordId) {
      currentRecord = null;
      originalRecord = null;
      clearForm();
      return;
    }

    const records = await window.aivicApi.list(1);
    if (records) {
      currentRecord = records.find(r => r.作業記録ID === recordId);
      originalRecord = { ...currentRecord }; // 元データを保存

      if (currentRecord) {
        // フォームに値を設定
        const workDate = new Date(currentRecord.作業日).toLocaleDateString('ja-JP');
        container.querySelector("#input-work-date").value = workDate;

        const startTime = new Date(currentRecord.作業開始時刻);
        const endTime = currentRecord.作業終了時刻? new Date(currentRecord.作業終了時刻) : null;

        container.querySelector("#input-start-time").value = startTime.toTimeString().substring(0, 5);
        if (endTime) {
          container.querySelector("#input-end-time").value = endTime.toTimeString().substring(0, 5);
        }

        container.querySelector("#select-work-item").value = currentRecord.作業種別 || "";
        container.querySelector("#textarea-work-content").value = currentRecord.作業内容 || "";
        container.querySelector("#input-break-time").value = "0";

        calculateDuration();
      }
    }
  });

  function clearForm() {
    container.querySelector("#input-work-date").value = "";
    container.querySelector("#input-start-time").value = "";
    container.querySelector("#input-end-time").value = "";
    container.querySelector("#display-work-duration").value = "";
    container.querySelector("#display-net-work-time").value = "";
    container.querySelector("#input-break-time").value = "";
    container.querySelector("#select-work-item").value = "";
    container.querySelector("#textarea-work-content").value = "";
    container.querySelector("#input-correction-reason").value = "";
    container.querySelector("#warning-area").style.display = "none";
    container.querySelector("#error-area").style.display = "none";
  }

  // 時刻変更時の計算
  container.querySelector("#input-start-time").addEventListener("change", calculateDuration);
  container.querySelector("#input-end-time").addEventListener("change", calculateDuration);
  container.querySelector("#input-break-time").addEventListener("input", calculateDuration);

  // 修正完了ボタン
  container.querySelector("#btn-save").addEventListener("click", async function() {
    if (!currentRecord) {
      showError("修正対象の作業記録を選択してください");
      return;
    }

    const startTime = container.querySelector("#input-start-time").value;
    const endTime = container.querySelector("#input-end-time").value;
    const breakTime = parseInt(container.querySelector("#input-break-time").value) || 0;
    const correctionReason = container.querySelector("#input-correction-reason").value.trim();
    const workContent = container.querySelector("#textarea-work-content").value.trim();

    // バリデーション
    if (!correctionReason) {
      showError("修正理由を入力してください");
      return;
    }

    if (!startTime || !endTime) {
      showError("作業開始時刻と終了時刻を入力してください");
      return;
    }

    const start = new Date(`2000-01-01 ${startTime}`);
    let end = new Date(`2000-01-01 ${endTime}`);
    if (end < start) {
      end.setDate(end.getDate() + 1);
    }

    const totalMinutes = Math.floor((end - start) / (1000 * 60));

    if (!validateTimes(start, end, totalMinutes, breakTime)) {
      return;
    }

    // 更新データを準備
    const updateData = {
      作業開始時刻: new Date(`${currentRecord.作業日.split('T')[0]} ${startTime}`).toISOString(),
      作業終了時刻: new Date(`${currentRecord.作業日.split('T')[0]} ${endTime}`).toISOString(),
      作業時間: totalMinutes - breakTime,
      作業種別: container.querySelector("#select-work-item").value,
      作業内容: workContent,
      更新日時: new Date().toISOString()
    };

    const result = await window.aivicApi.update(1, currentRecord.作業記録ID, updateData);
    if (result) {
      // 修正理由を異常値検出ログに記録
      await window.aivicApi.save(4, {
        検出対象テーブル: "作業記録",
        検出対象レコードID: currentRecord.作業記録ID,
        ユーザーID: currentRecord.作業員ID,
        異常値種別: "手動修正",
        検出項目: "工数修正",
        検出値: "修正実施",
