      <div style="margin-bottom: 8px;"><strong>終了時刻:</strong> ${endTime}</div>
      <div style="margin-bottom: 8px;"><strong>作業時間:</strong> ${originalRecord.作業時間 || 0}分</div>
      <div style="margin-bottom: 8px;"><strong>作業種別:</strong> ${originalRecord.作業種別 || ""}</div>
      <div style="margin-bottom: 8px;"><strong>作業内容:</strong> ${originalRecord.作業内容 || ""}</div>
    `;

    modal.style.display = "block";
