  // モーダル背景クリックで閉じる
  container.querySelector("#original-data-modal").addEventListener("click", function(e) {
    if (e.target === this) {
      this.style.display = "none";
    }
  });

  // 初期化
  loadWorkItems();
  loadWorkRecords();
}

function(container, apiUrl, tables) {
  let currentPreviewData = [];

  // 初期化時に作業員と作業項目のオプションを設定
  async function initializeOptions() {
    try {
      // 作業員データを取得
      const users = await window.aivicApi.list(0);
      const workersSelect = container.querySelector('#select-workers');
      workersSelect.innerHTML = '';
      if (users) {
        users.forEach(user => {
          if (user.有効フラグ) {
            const option = document.createElement('option');
            option.value = user.ユーザーID;
            option.textContent = user.氏名;
            workersSelect.appendChild(option);
          }
        });
      }

      // 作業項目データを取得
      const workItems = await window.aivicApi.list(3);
      const workItemsSelect = container.querySelector('#select-work-items');
      workItemsSelect.innerHTML = '';
      if (workItems) {
        workItems.forEach(item => {
          if (item.有効フラグ) {
            const option = document.createElement('option');
            option.value = item.作業項目ID;
            option.textContent = item.作業項目名;
            workItemsSelect.appendChild(option);
          }
        });
      }
    } catch (error) {
      console.error('オプション初期化エラー:', error);
    }
  }

  // エラーメッセージ表示
  function showError(message) {
    const errorDiv = container.querySelector('#error-message');
    errorDiv.textContent = message;
    errorDiv.style.display = 'block';
    setTimeout(() => {
      errorDiv.style.display = 'none';
    }, 5000);
  }

  // 成功メッセージ表示
  function showSuccess(message) {
    const successDiv = container.querySelector('#success-message');
    successDiv.textContent = message;
    successDiv.style.display = 'block';
    setTimeout(() => {
      successDiv.style.display = 'none';
    }, 3000);
  }

  // 条件バリデーション
  function validateConditions() {
    const startDate = container.querySelector('#input-start-date').value;
    const endDate = container.querySelector('#input-end-date').value;
    const outputFormat = container.querySelector('#select-output-format').value;
    const selectedWorkers = Array.from(container.querySelector('#select-workers').selectedOptions);

    if (!startDate || !endDate) {
      showError('抽出期間（開始日・終了日）を指定してください');
      return false;
    }

    if (new Date(startDate) > new Date(endDate)) {
      showError('開始日は終了日より前の日付を入力してください');
      return false;
    }

    if (!outputFormat) {
      showError('出力形式を選択してください');
      return false;
    }

    if (selectedWorkers.length === 0) {
      showError('作業員を選択してください');
      return false;
    }

    return true;
  }

  // プレビュー更新
  async function updatePreview() {
    const startDate = container.querySelector('#input-start-date').value;
    const endDate = container.querySelector('#input-end-date').value;
    const selectedWorkers = Array.from(container.querySelector('#select-workers').selectedOptions);
    const selectedWorkItems = Array.from(container.querySelector('#select-work-items').selectedOptions);
    const workLocation = container.querySelector('#input-work-location').value;
    const includeAnomaly = container.querySelector('#checkbox-include-anomaly').checked;
    const includeInterruption = container.querySelector('#checkbox-include-interruption').checked;
    const outputFormat = container.querySelector('#select-output-format').value;

    let previewText = '【抽出条件】\n';

    if (startDate && endDate) {
      previewText += `期間: ${startDate} ～ ${endDate}\n`;
    }

    if (selectedWorkers.length > 0) {
      const workerNames = selectedWorkers.map(opt => opt.textContent).join(', ');
      previewText += `作業員: ${workerNames}\n`;
    }

    if (selectedWorkItems.length > 0) {
      const itemNames = selectedWorkItems.map(opt => opt.textContent).join(', ');
      previewText += `作業項目: ${itemNames}\n`;
    }

    if (workLocation) {
      previewText += `作業場所: ${workLocation}\n`;
    }

    previewText += `異常値データ: ${includeAnomaly ? '含む' : '除外'}\n`;
    previewText += `中断記録: ${includeInterruption ? '含む' : '除外'}\n`;

    if (outputFormat) {
      previewText += `出力形式: ${outputFormat.toUpperCase()}\n`;
    }

    container.querySelector('#preview-content').textContent = previewText;

    // データ件数を計算
    try {
      const workRecords = await window.aivicApi.list(1);
      if (workRecords) {
        let filteredRecords = workRecords.filter(record => {
          const recordDate = new Date(record.作業日);
          const start = startDate ? new Date(startDate) : null;
          const end = endDate ? new Date(endDate) : null;

          if (start && recordDate < start) return false;
          if (end && recordDate > end) return false;

          if (selectedWorkers.length > 0) {
            const workerIds = selectedWorkers.map(opt => opt.value);
            if (!workerIds.includes(record.作業員ID)) return false;
          }

          if (workLocation && !record.作業場所.includes(workLocation)) return false;

          return true;
        });

        // 異常値フィルタリング
        if (!includeAnomaly) {
          const anomalyLogs = await window.aivicApi.list(4);
          if (anomalyLogs) {
            const anomalyRecordIds = anomalyLogs
              .filter(log => log.検出対象テーブル === '作業記録')
              .map(log => log.検出対象レコードID);
            filteredRecords = filteredRecords.filter(record => 
              !anomalyRecordIds.includes(record.作業記録ID)
            );
          }
        }

        currentPreviewData = filteredRecords;
        container.querySelector('#data-count').textContent = `${filteredRecords.length}件`;
      }
    } catch (error) {
      console.error('データ件数計算エラー:', error);
      container.querySelector('#data-count').textContent = '計算エラー';
    }
  }

  // CSV/Excel出力
  function exportData(format) {
    if (currentPreviewData.length === 0) {
      showError('抽出するデータがありません');
      return;
    }

    const headers = ['作業日', '作業員名', '作業開始時刻', '作業終了時刻', '作業時間', 'プロジェクト名', '作業場所', '作業種別', '作業内容', '進捗状況'];

    if (format === 'csv') {
      let csvContent = '\uFEFF' + headers.join(',') + '\n';

      currentPreviewData.forEach(record => {
        const row = [
          record.作業日 || '',
          record.作業員名 || '',
          record.作業開始時刻 || '',
          record.作業終了時刻 || '',
          record.作業時間 || '',
          record.プロジェクト名 || '',
          record.作業場所 || '',
          record.作業種別 || '',
          `"${(record.作業内容 || '').replace(/"/g, '""')}"`,
          record.進捗状況 || ''
        ];
        csvContent += row.join(',') + '\n';
      });

      const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
      const link = document.createElement('a');
      link.href = URL.createObjectURL(blob);
      link.download = `工数記録データ_${new Date().toISOString().slice(0, 10)}.csv`;
      link.click();

      showSuccess('CSVファイルをダウンロードしました');
    } else if (format === 'excel') {
      // 簡易Excel形式（実際にはCSVだが拡張子をxlsxに）
      let csvContent = '\uFEFF' + headers.join('\t') + '\n';

      currentPreviewData.forEach(record => {
        const row = [
          record.作業日 || '',
          record.作業員名 || '',
          record.作業開始時刻 || '',
          record.作業終了時刻 || '',
          record.作業時間 || '',
          record.プロジェクト名 || '',
          record.作業場所 || '',
          record.作業種別 || '',
          (record.作業内容 || '').replace(/\t/g, ' '),
          record.進捗状況 || ''
        ];
        csvContent += row.join('\t') + '\n';
      });

      const blob = new Blob([csvContent], { type: 'application/vnd.ms-excel;charset=utf-8;' });
      const link = document.createElement('a');
      link.href = URL.createObjectURL(blob);
      link.download = `工数記録データ_${new Date().toISOString().slice(0, 10)}.xlsx`;
      link.click();

      showSuccess('Excelファイルをダウンロードしました');
    }
  }

  // 条件クリア
  function clearConditions() {
    container.querySelector('#input-start-date').value = '';
    container.querySelector('#input-end-date').value = '';
    container.querySelector('#select-output-format').value = '';
    container.querySelector('#select-workers').selectedIndex = -1;
    container.querySelector('#select-work-items').selectedIndex = -1;
    container.querySelector('#input-work-location').value = '';
    container.querySelector('#checkbox-include-anomaly').checked = false;
    container.querySelector('#checkbox-include-interruption').checked = false;
    container.querySelector('#input-condition-name').value = '';
    container.querySelector('#preview-content').textContent = '条件を設定してプレビューボタンをクリックしてください';
    container.querySelector('#data-count').textContent = '0件';
    currentPreviewData = [];
  }

  // 条件保存
  function saveConditions() {
    const conditionName = container.querySelector('#input-condition-name').value;
    if (!conditionName) {
      showError('条件名を入力してください');
      return;
    }

    const conditions = {
      name: conditionName,
      startDate: container.querySelector('#input-start-date').value,
      endDate: container.querySelector('#input-end-date').value,
      outputFormat: container.querySelector('#select-output-format').value,
      selectedWorkers: Array.from(container.querySelector('#select-workers').selectedOptions).map(opt => opt.value),
      selectedWorkItems: Array.from(container.querySelector('#select-work-items').selectedOptions).map(opt => opt.value),
      workLocation: container.querySelector('#input-work-location').value,
      includeAnomaly: container.querySelector('#checkbox-include-anomaly').checked,
      includeInterruption: container.querySelector('#checkbox-include-interruption').checked,
      savedAt: new Date().toISOString()
    };

    // ローカルストレージに保存
    const savedConditions = JSON.parse(localStorage.getItem('extractionConditions') || '[]');
    savedConditions.push(conditions);
    localStorage.setItem('extractionConditions', JSON.stringify(savedConditions));

    showSuccess('抽出条件を保存しました');
  }

  // イベントリスナー設定
  container.querySelector('#btn-back').addEventListener('click', () => {
    window.showScreen("scr-1778907145716");
  });

  container.querySelector('#btn-preview').addEventListener('click', updatePreview);

  container.querySelector('#btn-clear-conditions').addEventListener('click', clearConditions);

  container.querySelector('#btn-save-conditions').addEventListener('click', saveConditions);

  container.querySelector('#btn-extract').addEventListener('click', async () => {
    if (!validateConditions()) return;

    const loadingIndicator = container.querySelector('#loading-indicator');
    loadingIndicator.style.display = 'block';

    try {
      await updatePreview();

      setTimeout(() => {
        loadingIndicator.style.display = 'none';
        const outputFormat = container.querySelector('#select-output-format').value;
        exportData(outputFormat);
      }, 1500); // 処理時間をシミュレート

    } catch (error) {
      loadingIndicator.style.display = 'none';
      if (error.message.includes('timeout')) {
        showError('大量データ抽出処理がタイムアウトしました。条件を絞り込んでください。');
      } else {
        showError('データ抽出中にエラーが発生しました');
      }
    }
  });

  // 初期化
  initializeOptions();
}

function(container, apiUrl, tables) {
  const tbody = container.querySelector('#records-tbody');
  const emptyMessage = container.querySelector('#empty-message');
  const detailModal = container.querySelector('#detail-modal');
  const deleteModal = container.querySelector('#delete-modal');
  const approveModal = container.querySelector('#approve-modal');

  let currentDeleteId = null;
  let currentApproveId = null;
  let allRecords = [];
  let allUsers = [];
  let allBreaks = [];

  // ユーザー情報とブレイク情報を取得
  async function loadReferenceData() {
    try {
      allUsers = await window.aivicApi.list(0) || [];
      allBreaks = await window.aivicApi.list(2) || [];
    } catch (error) {
      console.error('参照データの読み込みエラー:', error);
    }
  }

  // 時間フォーマット関数
  function formatTime(timestamp) {
    if (!timestamp) return '';
    const date = new Date(timestamp);
    return date.toLocaleTimeString('ja-JP', { hour: '2-digit', minute: '2-digit' });
  }

  // 日付フォーマット関数
  function formatDate(timestamp) {
    if (!timestamp) return '';
    const date = new Date(timestamp);
    return date.toLocaleDateString('ja-JP');
  }

  // 作業時間計算（分）
  function calculateWorkTime(startTime, endTime) {
    if (!startTime || !endTime) return 0;
    const start = new Date(startTime);
    const end = new Date(endTime);
    return Math.max(0, Math.floor((end - start) / (1000 * 60)));
  }

  // 中断時間計算（分）
  function calculateBreakTime(recordId) {
    const breaks = allBreaks.filter(b => b.作業記録ID === recordId);
    return breaks.reduce((total, b) => {
      if (b.中断開始日時 && b.中断終了日時) {
        const start = new Date(b.中断開始日時);
        const end = new Date(b.中断終了日時);
        return total + Math.max(0, Math.floor((end - start) / (1000 * 60)));
      }
      return total;
    }, 0);
  }

  // 時間フォーマット（分を時間:分に変換）
  function formatMinutes(minutes) {
    if (!minutes || minutes === 0) return '0分';
    const hours = Math.floor(minutes / 60);
    const mins = minutes % 60;
    if (hours === 0) return `${mins}分`;
    if (mins === 0) return `${hours}時間`;
    return `${hours}時間${mins}分`;
  }

  // ユーザー名取得
  function getUserName(userId) {
    const user = allUsers.find(u => u.ユーザーID === userId);
    return user ? user.氏名 : 'Unknown';
  }

  // 異常値チェック
  function checkAnomalies(record) {
    const warnings = [];
    const workTime = calculateWorkTime(record.作業開始時刻, record.作業終了時刻);
    const breakTime = calculateBreakTime(record.作業記録ID);

    // 24時間を超える作業時間
    if (workTime > 1440) {
      warnings.push('24時間を超える作業時間');
    }

    // 終了時刻が開始時刻より早い
    if (record.作業開始時刻&& record.作業終了時刻) {
      const start = new Date(record.作業開始時刻);
      const end = new Date(record.作業終了時刻);
      if (end < start) {
        warnings.push('終了時刻が開始時刻より早い');
      }
    }

    // 中断時間が実働時間を超える
    if (breakTime > workTime) {
      warnings.push('中断時間が実働時間を超過');
    }

    return warnings;
  }

  // テーブル再描画関数
  function renderRows(rows) {
    if (!rows || rows.length === 0) {
      tbody.innerHTML = '';
      emptyMessage.classList.remove('hidden');
      return;
    }

    emptyMessage.classList.add('hidden');

    tbody.innerHTML = rows.map(record => {
      const workTime = calculateWorkTime(record.作業開始時刻, record.作業終了時刻);
      const breakTime = calculateBreakTime(record.作業記録ID);
      const warnings = checkAnomalies(record);
      const hasWarnings = warnings.length > 0;
      const userName = getUserName(record.作業員ID);
      const isApproved = record.承認状態 === '承認済み';

      return `
        <tr data-id="${record.作業記録ID}" style="${hasWarnings ? 'background: rgba(255, 193, 7, 0.1);' : ''}">
          <td>${formatDate(record.作業日)}</td>
          <td>${userName}</td>
          <td>${formatTime(record.作業開始時刻)}</td>
          <td>${formatTime(record.作業終了時刻)}</td>
          <td>${formatMinutes(workTime)}</td>
          <td>${formatMinutes(breakTime)}</td>
          <td style="max-width: 200px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap;">${record.作業内容 || ''}</td>
          <td>${record.作業場所 || ''}</td>
          <td>
            <span style="padding: 2px 6px; border-radius: 4px; font-size: 11px; ${isApproved ? 'background: rgba(40, 167, 69, 0.2); color: #28a745;' : 'background: rgba(255, 193, 7, 0.2); color: #ffc107;'}">${record.承認状態}</span>
            ${hasWarnings ? '<span style="color: #dc3545; margin-left: 4px; font-size: 14px;" title="' + warnings.join(', ') + '">⚠️</span>' : ''}
          </td>
          <td>
            <div style="display: flex; gap: 4px;">
              <button class="action-btn secondary detail-btn" data-id="${record.作業記録ID}" style="padding: 4px 8px; font-size: 11px;">詳細</button>
              ${!isApproved ? `<button class="action-btn secondary edit-btn" data-id="${record.作業記録ID}" style="padding: 4px 8px; font-size: 11px;">修正</button>` : ''}
              ${record.承認状態 === '未承認' ? `<button class="action-btn approve-btn" data-id="${record.作業記録ID}" style="padding: 4px 8px; font-size: 11px;">承認</button>` : ''}
              ${!isApproved ? `<button class="action-btn secondary delete-btn" data-id="${record.作業記録ID}" style="padding: 4px 8px; font-size: 11px; background: #dc3545; color: #fff;">削除</button>` : ''}
            </div>
          </td>
        </tr>
      `;
    }).join('');
  }

  // 詳細表示
  function showDetail(recordId) {
    const record = allRecords.find(r => r.作業記録ID === recordId);
    if (!record) return;

    const workTime = calculateWorkTime(record.作業開始時刻, record.作業終了時刻);
    const breakTime = calculateBreakTime(record.作業記録ID);
    const userName = getUserName(record.作業員ID);
    const approverName = record.承認者ID ? getUserName(record.承認者ID) : '';

    const breaks = allBreaks.filter(b => b.作業記録ID === recordId);

    container.querySelector('#detail-content').innerHTML = `
      <div style="display: grid; grid-template-columns: 1fr 1fr; gap: 16px;">
        <div>
          <h4 style="font-size: 13px; font-weight: 600; margin: 0 0 8px 0; color: var(--text);">基本情報</h4>
          <div style="margin-bottom: 8px;"><strong>作業日:</strong> ${formatDate(record.作業日)}</div>
          <div style="margin-bottom: 8px;"><strong>作業者:</strong> ${userName}</div>
          <div style="margin-bottom: 8px;"><strong>プロジェクト:</strong> ${record.プロジェクト名 || ''}</div>
          <div style="margin-bottom: 8px;"><strong>作業場所:</strong> ${record.作業場所 || ''}</div>
          <div style="margin-bottom: 8px;"><strong>作業種別:</strong> ${record.作業種別 || ''}</div>
          <div style="margin-bottom: 8px;"><strong>進捗状況:</strong> ${record.進捗状況 || ''}</div>
        </div>
        <div>
          <h4 style="font-size: 13px; font-weight: 600; margin: 0 0 8px 0; color: var(--text);">時間情報</h4>
          <div style="margin-bottom: 8px;"><strong>開始時刻:</strong> ${formatTime(record.作業開始時刻)}</div>
          <div style="margin-bottom: 8px;"><strong>終了時刻:</strong> ${formatTime(record.作業終了時刻)}</div>
          <div style="margin-bottom: 8px;"><strong>実働時間:</strong> ${formatMinutes(workTime)}</div>
          <div style="margin-bottom: 8px;"><strong>中断時間:</strong> ${formatMinutes(breakTime)}</div>
          <div style="margin-bottom: 8px;"><strong>承認状態:</strong> ${record.承認状態}</div>
          ${approverName ? `<div style="margin-bottom: 8px;"><strong>承認者:</strong> ${approverName}</div>` : ''}
          ${record.承認日時 ? `<div style="margin-bottom: 8px;"><strong>承認日時:</strong> ${formatDate(record.承認日時)} ${formatTime(record.承認日時)}</div>` : ''}
        </div>
      </div>
      <div style="margin-top: 16px;">
        <h4 style="font-size: 13px; font-weight: 600; margin: 0 0 8px 0; color: var(--text);">作業内容</h4>
        <div style="background: rgba(0,0,0,0.25); padding: 8px; border-radius: 4px; white-space: pre-wrap;">${record.作業内容 || ''}</div>
      </div>
      ${record.備考 ? `
        <div style="margin-top: 16px;">
          <h4 style="font-size: 13px; font-weight: 600; margin: 0 0 8px 0; color: var(--text);">備考</h4>
          <div style="background: rgba(0,0,0,0.25); padding: 8px; border-radius: 4px; white-space: pre-wrap;">${record.備考}</div>
        </div>
      ` : ''}
      ${breaks.length > 0 ? `
        <div style="margin-top: 16px;">
          <h4 style="font-size: 13px; font-weight: 600; margin: 0 0 8px 0; color: var(--text);">中断記録</h4>
          ${breaks.map(b => `
            <div style="background: rgba(0,0,0,0.25); padding: 8px; border-radius: 4px; margin-bottom: 4px;">
              <div><strong>期間:</strong> ${formatTime(b.中断開始日時)} - ${formatTime(b.中断終了日時)}</div>
              <div><strong>理由:</strong> ${b.中断理由区分} ${b.中断理由詳細 ? '(' + b.中断理由詳細 + ')' : ''}</div>
            </div>
          `).join('')}
        </div>
      ` : ''}
    `;

    detailModal.classList.remove('hidden');
  }

  // CSVエクスポート
  function exportCSV() {
    const headers = ['作業日', '作業者', '開始時刻', '終了時刻', '実働時間', '中断時間', '作業内容', '作業場所', '承認状態'];
    const csvData = allRecords.map(record => {
      const workTime = calculateWorkTime(record.作業開始時刻, record.作業終了時刻);
      const breakTime = calculateBreakTime(record.作業記録ID);
      const userName = getUserName(record.作業員ID);

      return [
        formatDate(record.作業日),
        userName,
        formatTime(record.作業開始時刻),
        formatTime(record.作業終了時刻),
        formatMinutes(workTime),
        formatMinutes(breakTime),
        (record.作業内容 || '').replace(/"/g, '""'),
        (record.作業場所 || '').replace(/"/g, '""'),
        record.承認状態
      ].map(field => `"${field}"`).join(',');
    });

    const csv = '\uFEFF' + [headers.join(','), ...csvData].join('\n');
    const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `工数記録_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  }

  // 初期データ読み込み
  async function loadData() {
    await loadReferenceData();
    try {
      allRecords = await window.aivicApi.list(1) || [];
      renderRows(allRecords);
    } catch (error) {
      console.error('データ読み込みエラー:', error);
      allRecords = tables[1]?.records || [];
      renderRows(allRecords);
    }
  }

  // 検索機能
  container.querySelector('#btn-search').addEventListener('click', async () => {
    const filterDate = container.querySelector('#filter-date').value;
    const startDate = container.querySelector('#filter-start-date').value;
    const endDate = container.querySelector('#filter-end-date').value;

    // 日付バリデーション
    if (startDate && endDate && new Date(startDate) > new Date(endDate)) {
      alert('開始日は終了日より前の日付を指定してください');
      return;
    }

    let filteredRecords = [...allRecords];

    if (filterDate) {
      filteredRecords = filteredRecords.filter(record => {
        const recordDate = new Date(record.作業日).toISOString().split('T')[0];
        return recordDate === filterDate;
      });
    } else if (startDate || endDate) {
      filteredRecords = filteredRecords.filter(record => {
        const recordDate = new Date(record.作業日);
        const start = startDate ? new Date(startDate) : new Date('1900-01-01');
        const end = endDate ? new Date(endDate) : new Date('2100-12-31');
        return recordDate >= start && recordDate <= end;
      });
    }

    renderRows(filteredRecords);
  });

  // CSVエクスポート
  container.querySelector('#btn-export').addEventListener('click', exportCSV);

  // イベントデリゲーション
  container.addEventListener('click', async (e) => {
    // 詳細表示
    const detailBtn = e.target.closest('.detail-btn');
    if (detailBtn) {
      showDetail(detailBtn.dataset.id);
      return;
    }

    // 編集
    const editBtn = e.target.closest('.edit-btn');
    if (editBtn) {
      window.showScreen('scr-1778907343735');
      return;
    }

    // 削除
    const deleteBtn = e.target.closest('.delete-btn');
    if (deleteBtn) {
      currentDeleteId = deleteBtn.dataset.id;
      deleteModal.classList.remove('hidden');
      return;
    }

    // 承認
    const approveBtn = e.target.closest('.approve-btn');
    if (approveBtn) {
      currentApproveId = approveBtn.dataset.id;
      approveModal.classList.remove('hidden');
      return;
    }

    // モーダル閉じる
    if (e.target.id === 'close-modal') {
      detailModal.classList.add('hidden');
    }

    if (e.target.id === 'cancel-delete') {
      deleteModal.classList.add('hidden');
      currentDeleteId = null;
    }

    if (e.target.id === 'cancel-approve') {
      approveModal.classList.add('hidden');
      currentApproveId = null;
    }

    // 削除実行
    if (e.target.id === 'confirm-delete' && currentDeleteId) {
      try {
        await window.aivicApi.delete(1, currentDeleteId);
        deleteModal.classList.add('hidden');
        currentDeleteId = null;
        await loadData();
      } catch (error) {
        alert('削除に失敗しました');
      }
    }

    // 承認実行
    if (e.target.id === 'confirm-approve' && currentApproveId) {
      try {
        await window.aivicApi.update(1, currentApproveId, {
          承認状態: '承認済み',
          承認日時: new Date().toISOString()
        });
        approveModal.classList.add('hidden');
        currentApproveId = null;
        await loadData();
      } catch (error) {
        alert('承認に失敗しました');
      }
    }
  });

  // モーダル外クリックで閉じる
  [detailModal, deleteModal, approveModal].forEach(modal => {
    modal.addEventListener('click', (e) => {
      if (e.target === modal) {
        modal.classList.add('hidden');
      }
    });
  });

  // 初期化
  loadData();
}

function(container, apiUrl, tables) {
  let breakRecords = [];
  let tempSaveData = null;

  // 今日の日付を設定
  const today = new Date().toISOString().split('T')[0];
  container.querySelector('#input-work-date').value = today;

  // 作業項目マスタの読み込み
  async function loadWorkItems() {
    const workItems = await window.aivicApi.list(3); // 作業項目マスタ
    const select = container.querySelector('#select-work-item');
    select.innerHTML = '<option value="">選択してください</option>';
    if (workItems) {
      workItems.filter(item => item.有効フラグ).forEach(item => {
        const option = document.createElement('option');
        option.value = item.作業項目ID;
        option.textContent = `${item.作業項目コード} - ${item.作業項目名}`;
        select.appendChild(option);
      });
    }
  }

  // 工数時間の自動計算
  function calculateHours() {
    const startTime = container.querySelector('#input-start-time').value;
    const endTime = container.querySelector('#input-end-time').value;
    const breakTime = parseInt(container.querySelector('#input-break-time').value) || 0;

    if (startTime && endTime) {
      const start = new Date(`2000-01-01T${startTime}`);
      const end = new Date(`2000-01-01T${endTime}`);

      if (end <= start) {
        container.querySelector('#calculated-hours').textContent = 'エラー';
        return 0;
      }

      const diffMs = end - start;
      const totalMinutes = Math.floor(diffMs / (1000 * 60));
      const workMinutes = Math.max(0, totalMinutes - breakTime);

      // 中断記録の時間も差し引く
      const totalBreakMinutes = breakRecords.reduce((sum, record) => {
        if (record.中断開始日時 && record.中断終了日時) {
          const breakStart = new Date(`2000-01-01T${record.中断開始日時.split('T')[1]}`);
          const breakEnd = new Date(`2000-01-01T${record.中断終了日時.split('T')[1]}`);
          return sum + Math.floor((breakEnd - breakStart) / (1000 * 60));
        }
        return sum;
      }, 0);

      const finalMinutes = Math.max(0, workMinutes - totalBreakMinutes);
      const hours = (finalMinutes / 60).toFixed(1);
      container.querySelector('#calculated-hours').textContent = `${hours}h`;
      return finalMinutes;
    }

    container.querySelector('#calculated-hours').textContent = '0.0h';
    return 0;
  }

  // 文字数カウント
  function updateCharCount() {
    const textarea = container.querySelector('#input-work-detail');
    const count = textarea.value.length;
    container.querySelector('#char-count').textContent = count;

    if (count > 1000) {
      container.querySelector('#char-count').style.color = '#ef4444';
    } else {
      container.querySelector('#char-count').style.color = 'var(--text-muted)';
    }
  }

  // バリデーション
  function validateForm() {
    const errors = [];
    const workDate = container.querySelector('#input-work-date').value;
    const project = container.querySelector('#select-project').value;
    const workItem = container.querySelector('#select-work-item').value;
    const workLocation = container.querySelector('#select-work-location').value;
    const workType = container.querySelector('#select-work-type').value;
    const startTime = container.querySelector('#input-start-time').value;
    const endTime = container.querySelector('#input-end-time').value;
    const workDetail = container.querySelector('#input-work-detail').value;
    const breakTime = parseInt(container.querySelector('#input-break-time').value) || 0;

    // 必須項目チェック
    if (!workDate) errors.push('作業日付は必須です');
    if (!project) errors.push('プロジェクト名は必須です');
    if (!workItem) errors.push('作業項目は必須です');
    if (!workLocation) errors.push('作業場所は必須です');
    if (!workType) errors.push('作業種別は必須です');
    if (!startTime) errors.push('開始時刻は必須です');
    if (!endTime) errors.push('終了時刻は必須です');
    if (!workDetail.trim()) errors.push('作業内容詳細は必須です');

    // 日付チェック
    if (workDate && new Date(workDate) > new Date(today)) {
      errors.push('未来日付は選択できません');
    }

    // 時刻チェック
    if (startTime && endTime) {
      const start = new Date(`2000-01-01T${startTime}`);
      const end = new Date(`2000-01-01T${endTime}`);

      if (end <= start) {
        errors.push('開始時刻が終了時刻より後になっています');
      } else {
        const diffMs = end - start;
        const totalMinutes = Math.floor(diffMs / (1000 * 60));

        if (totalMinutes >= 24 * 60) {
          errors.push('24時間以上の作業時間は入力できません');
        }

        if (breakTime > totalMinutes) {
          errors.push('中断時間は作業時間を超過できません');
        }
      }
    }

    // 文字数チェック
    if (workDetail.length > 1000) {
      errors.push('作業内容詳細は1000文字以内で入力してください');
    }

    return errors;
  }

  // エラー表示
  function showErrors(errors) {
    const errorDiv = container.querySelector('#error-messages');
    const errorList = container.querySelector('#error-list');

    if (errors.length > 0) {
      errorList.innerHTML = errors.map(error => `<li>${error}</li>`).join('');
      errorDiv.style.display = 'block';
    } else {
      errorDiv.style.display = 'none';
    }
  }

  // 中断記録の追加
  function addBreakRecord() {
    const breakStart = prompt('中断開始時刻を入力してください (HH:MM)');
    if (!breakStart || !/^\d{2}:\d{2}$/.test(breakStart)) return;

    const breakEnd = prompt('中断終了時刻を入力してください (HH:MM)');
    if (!breakEnd || !/^\d{2}:\d{2}$/.test(breakEnd)) return;

    const reason = prompt('中断理由を入力してください');
    if (!reason) return;

    const breakRecord = {
      中断記録ID: `break_${Date.now()}`,
      中断開始日時: `${container.querySelector('#input-work-date').value}T${breakStart}`,
      中断終了日時: `${container.querySelector('#input-work-date').value}T${breakEnd}`,
      中断理由区分: '休憩',
      中断理由詳細: reason,
      対応状況: '解決済み'
    };

    breakRecords.push(breakRecord);
    renderBreakRecords();
    calculateHours();
  }

  // 中断記録の表示
  function renderBreakRecords() {
    const tbody = container.querySelector('#break-records-tbody');
    const recordsDiv = container.querySelector('#break-records');

    if (breakRecords.length > 0) {
      recordsDiv.style.display = 'block';
      tbody.innerHTML = breakRecords.map((record, index) => {
        const startTime = record.中断開始日時.split('T')[1];
        const endTime = record.中断終了日時.split('T')[1];
        const start = new Date(`2000-01-01T${startTime}`);
        const end = new Date(`2000-01-01T${endTime}`);
        const minutes = Math.floor((end - start) / (1000 * 60));

        return `
          <tr>
            <td style="padding: 6px 8px; font-size: 12px;">${startTime}</td>
            <td style="padding: 6px 8px; font-size: 12px;">${endTime}</td>
            <td style="padding: 6px 8px; font-size: 12px;">${record.中断理由詳細}</td>
            <td style="padding: 6px 8px; font-size: 12px;">${minutes}分</td>
            <td style="padding: 6px 8px;">
              <button class="action-btn secondary delete-break-btn" data-index="${index}" style="font-size: 11px; padding: 2px 6px;">削除</button>
            </td>
          </tr>
        `;
      }).join('');
    } else {
      recordsDiv.style.display = 'none';
    }
  }

  // フォームクリア
  function clearForm() {
    container.querySelector('#input-work-date').value = today;
    container.querySelector('#select-project').value = '';
    container.querySelector('#select-work-item').value = '';
    container.querySelector('#select-work-location').value = '';
    container.querySelector('#select-work-type').value = '';
    container.querySelector('#input-start-time').value = '';
    container.querySelector('#input-end-time').value = '';
    container.querySelector('#input-break-time').value = '';
    container.querySelector('#input-work-detail').value = '';
    container.querySelector('#input-remarks').value = '';
    breakRecords = [];
    renderBreakRecords();
    calculateHours();
    updateCharCount();
    showErrors([]);
  }

  // フォームデータ収集
  function getFormData() {
    return {
      作業員ID: 'user_001', // 現在のユーザーID（実際は認証情報から取得）
      作業日: container.querySelector('#input-work-date').value,
      作業開始時刻: `${container.querySelector('#input-work-date').value}T${container.querySelector('#input-start-time').value}`,
      作業終了時刻: `${container.querySelector('#input-work-date').value}T${container.querySelector('#input-end-time').value}`,
      作業時間: calculateHours(),
      プロジェクト名: container.querySelector('#select-project').value,
      作業場所: container.querySelector('#select-work-location').value,
      作業種別: container.querySelector('#select-work-type').value,
      作業内容: container.querySelector('#input-work-detail').value,
      進捗状況: '完了',
      備考: container.querySelector('#input-remarks').value,
      承認状態: '未承認',
      作成者ID: 'user_001'
    };
  }

  // イベントリスナー設定
  container.querySelector('#input-start-time').addEventListener('change', calculateHours);
  container.querySelector('#input-end-time').addEventListener('change', calculateHours);
  container.querySelector('#input-break-time').addEventListener('input', calculateHours);
  container.querySelector('#input-work-detail').addEventListener('input', updateCharCount);

  // 中断記録追加
  container.querySelector('#btn-add-break').addEventListener('click', addBreakRecord);

  // 中断記録削除
  container.addEventListener('click', (e) => {
    const deleteBtn = e.target.closest('.delete-break-btn');
    if (deleteBtn) {
      const index = parseInt(deleteBtn.dataset.index);
      breakRecords.splice(index, 1);
      renderBreakRecords();
      calculateHours();
    }
  });

  // 一時保存
  container.querySelector('#btn-temp-save').addEventListener('click', async () => {
    const errors = validateForm();
    if (errors.length > 0) {
      showErrors(errors);
      return;
    }

    tempSaveData = getFormData();
    tempSaveData.承認状態 = '一時保存';

    const saved = await window.aivicApi.save(1, tempSaveData); // 作業記録テーブル
    if (saved) {
      alert('一時保存しました');
      showErrors([]);
    }
  });

  // 記録確定
  container.querySelector('#btn-save').addEventListener('click', async () => {
    const errors = validateForm();
    if (errors.length > 0) {
      showErrors(errors);
      return;
    }

    if (!confirm('工数記録を確定しますか？')) return;

    const formData = getFormData();
    const saved = await window.aivicApi.save(1, formData); // 作業記録テーブル

    if (saved) {
      // 中断記録も保存
      for (const breakRecord of breakRecords) {
        breakRecord.作業記録ID = saved.作業記録ID;
        breakRecord.記録者ID = 'user_001';
        await window.aivicApi.save(2, breakRecord); // 中断記録テーブル
      }

      alert('工数記録を登録しました');
      clearForm();
    }
  });

  // キャンセル
  container.querySelector('#btn-cancel').addEventListener('click', () => {
    if (confirm('入力内容をクリアしますか？')) {
      clearForm();
    }
  });

  // 画面遷移
  container.querySelector('#btn-history').addEventListener('click', () => {
    window.showScreen('scr-1778907145716'); // 作業履歴一覧画面
  });

  container.querySelector('#btn-anomaly').addEventListener('click', () => {
    window.showScreen('scr-1778907170814'); // 異常値検出ログ画面
  });

  // 初期化
  loadWorkItems();
  updateCharCount();
}
